dotnetSource "LawSpec.Runtime/Mailbox.fs" = "namespace LawSpec.Runtime\n\nopen System\nopen System.Diagnostics\nopen System.Threading\nopen System.Threading.Tasks\nopen System.Numerics\nopen System.Text\n\n/// A typed mailbox of portable values. Native conversion and Clock callbacks\n/// run in the caller; the queue never runs application code. Closing refuses\n/// new sends and lets accepted values drain. A served mailbox belongs to its\n/// node, and a remote send completes once the mailbox has the value.\n/// ref:DEC-actors-otp-supervision ref:DEC-distribution-canonical-wire\n[<Sealed; AllowNullLiteral>]\ntype Mailbox private (network: (Node * string * Map<string, Descriptors.Descriptor> * Descriptors.Descriptor) option) as this =\n    let gate = obj ()\n    let queue = Collections.Generic.Queue<Value>()\n    let mutable closed = false\n    let mutable stopped = false\n    let mutable reader: TaskCompletionSource<Result<Value, string>> option = None\n    let fail reason : 'a = Fail.raiseWith \"Mailbox\" reason\n    let address =\n        match network with\n        | None -> None\n        | Some(node, name, _, _) ->\n            let a = node.RegisterReceiver(name, fun frame -> this.Incoming frame)\n            node.Adopt this\n            Some a\n\n    /// A local mailbox.\n    new() = new Mailbox(None)\n\n    /// A mailbox served at a name on a node, of values of a descriptor text.\n    static member Serve(node: Node, name: string, descriptor: string) =\n        let table, d = Descriptors.fromText descriptor\n        new Mailbox(Some(node, name, table, d))\n\n    member private this.Incoming(frame: Wire.Frame) =\n        let node, _, table, d =\n            match network with\n            | Some n -> n\n            | None -> fail \"local_mailbox\"\n        let status, body =\n            if closed then 2, \"the mailbox is closed\"\n            elif frame.Kind <> \"mail\" then 3, \"not a mailbox request\"\n            else\n                try\n                    this.Enqueue(Descriptors.decode d frame.Payload table)\n                    0, \"\"\n                with _ -> 3, \"not a message of this mailbox\"\n        if frame.Id <> 0UL then node.Reply(frame.Source, frame.Id, status, Encoding.UTF8.GetBytes body)\n\n    member private this.Enqueue(value: Value) =\n        let waiting =\n            lock gate (fun () ->\n                match reader with\n                | Some r ->\n                    reader <- None\n                    Some r\n                | None ->\n                    queue.Enqueue value\n                    None)\n        waiting |> Option.iter (fun r -> r.TrySetResult(Ok value) |> ignore)\n\n    /// The served mailbox's address.\n    member _.Address =\n        match address with\n        | Some a -> a\n        | None -> fail \"local_mailbox\"\n\n    /// Add a value, unless the mailbox is closed.\n    member this.Send(value: Value) =\n        lock gate (fun () -> if closed || stopped then fail \"closed\")\n        this.Enqueue value\n\n    member private this.Wait(deadline: int64 option) : Value option =\n        let pending =\n            lock gate (fun () ->\n                if reader.IsSome then fail \"already_receiving\"\n                if queue.Count > 0 then Choice1Of2(Some(queue.Dequeue()))\n                elif closed || stopped then fail \"closed\"\n                else\n                    let r = TaskCompletionSource<Result<Value, string>>(TaskCreationOptions.RunContinuationsAsynchronously)\n                    reader <- Some r\n                    Choice2Of2 r)\n        match pending with\n        | Choice1Of2 value -> value\n        | Choice2Of2 r ->\n            let finished =\n                match deadline with\n                | None -> r.Task.Wait(Timeout.Infinite)\n                | Some micros ->\n                    let left = micros - Stopwatch.GetTimestamp() * 1_000_000L / Stopwatch.Frequency\n                    left > 0L && r.Task.Wait(TimeSpan.FromMilliseconds(float ((left + 999L) / 1000L)))\n            let outcome () = match r.Task.Result with Ok v -> Some v | Error e -> fail e\n            if finished then outcome ()\n            else\n                let raced =\n                    lock gate (fun () ->\n                        match reader with\n                        | Some current when obj.ReferenceEquals(current, r) ->\n                            reader <- None\n                            false\n                        | _ -> true)\n                if raced then outcome () else None\n\n    /// The next value, waiting for one.\n    member this.Receive() : Value =\n        match this.Wait None with\n        | Some value -> value\n        | None -> fail \"closed\"\n\n    /// The next value within some microseconds, or none (a Maybe).\n    member this.ReceiveWithin(micros: BigInteger) : Value =\n        let now = Stopwatch.GetTimestamp() * 1_000_000L / Stopwatch.Frequency\n        match this.Wait(Some(now + int64 (BigInteger.Max(BigInteger.Zero, micros)))) with\n        | Some value -> Data(\"Maybe::Just\", [ value ])\n        | None -> Data(\"Maybe::Nothing\", [])\n\n    /// As ReceiveWithin, timed by the Clock in scope: the real clock waits;\n    /// any other clock (the virtual one) takes what is there, then sleeps.\n    member this.ReceiveWithClock(micros: BigInteger, schema: Schema.Schema) : Value =\n        let rec real h =\n            match h with\n            | Effects.Recording(_, inner) -> real inner\n            | Effects.Stateful _ -> false\n            | Effects.Stateless _ -> true\n        let handler = Effects.handler schema \"lawspec.time::ability::Clock\"\n        if real handler then this.ReceiveWithin micros\n        else\n            let now = Stopwatch.GetTimestamp() * 1_000_000L / Stopwatch.Frequency\n            match this.Wait(Some now) with\n            | Some value -> Data(\"Maybe::Just\", [ value ])\n            | None ->\n                Effects.invoke handler schema \"sleep\" [ Data(\"lawspec.time::type::Duration::Duration\", [ Int(BigInteger.Max(BigInteger.Zero, micros)) ]) ] |> ignore\n                Data(\"Maybe::Nothing\", [])\n\n    /// Refuse new values; accepted ones still drain.\n    member this.Close() =\n        let waiting =\n            lock gate (fun () ->\n                closed <- true\n                if queue.Count = 0 then\n                    let r = reader\n                    reader <- None\n                    r\n                else None)\n        waiting |> Option.iter (fun r -> r.TrySetResult(Error \"closed\") |> ignore)\n\n    /// Stop the mailbox: a waiting reader fails, and a served one leaves its node.\n    member this.Stop() =\n        let waiting =\n            lock gate (fun () ->\n                stopped <- true\n                let r = reader\n                reader <- None\n                r)\n        waiting |> Option.iter (fun r -> r.TrySetResult(Error \"closed\") |> ignore)\n        match network with\n        | Some(node, name, _, _) -> (try node.Unregister name with _ -> ())\n        | None -> ()\n\n    interface IDisposable with\n        member this.Dispose() = this.Stop()\n\n/// Sending to a mailbox on another node.\n[<Sealed>]\ntype MailboxSender(node: Node, address: string, descriptor: string, timeout: int) =\n    do if timeout <= 0 then Fail.raiseWith \"Mailbox\" \"invalid_sender\"\n    let table, d = Descriptors.fromText descriptor\n\n    /// Send, waiting until the mailbox has the value.\n    member _.Send(value: Value) =\n        match node.Request(address, \"mail\", Descriptors.encode d value table, timeout) with\n        | 0, _ -> ()\n        | 2, _ -> Fail.raiseWith \"Mailbox\" \"closed\"\n        | status, body -> Fail.raiseWith \"Mailbox\" (sprintf \"remote %d %s\" status (Encoding.UTF8.GetString body))\n\n/// Mailboxes, as generated code opens and uses them.\nmodule Mailboxes =\n    [<CompiledName(\"Open\")>]\n    let openMailbox () = new Mailbox()\n\n    /// A mailbox for a body, stopped after it.\n    [<CompiledName(\"WithMailbox\")>]\n    let withMailbox (body: Mailbox -> 'a) : 'a =\n        use box = new Mailbox()\n        body box\n\n    [<CompiledName(\"Serve\")>]\n    let serve (node: Node) (name: string) (descriptor: string) = Mailbox.Serve(node, name, descriptor)\n\n    [<CompiledName(\"Connect\")>]\n    let connect (node: Node) (address: string) (descriptor: string) (timeout: int) = MailboxSender(node, address, descriptor, timeout)\n"
dotnetSource "LawSpec.Runtime/MemoryNetwork.fs" = "namespace LawSpec.Runtime\n\nopen System\nopen System.Threading\nopen System.Threading.Tasks\nopen System.Numerics\n\n/// What happened to a frame sent on a memory network.\ntype MemoryEvent =\n    { Source: string\n      To: string\n      Frame: byte[]\n      Outcome: string\n      /// The delay slots of each copy (two when the frame was duplicated).\n      DelaySlots: int list }\n\n/// The options of an in-memory network: a seed for its faults, the chances\n/// of losing and of duplicating a frame, the most a frame is delayed (in\n/// seconds), and whether it records every frame.\ntype MemoryOptions =\n    { Seed: BigInteger\n      Loss: float\n      Duplicate: float\n      Delay: float\n      Record: bool }\n\n/// An owned in-memory packet transport with seeded loss, duplication and\n/// delay. Frames can overtake each other; reliability belongs to the node and\n/// the channel protocol above it, and no application code runs here.\n/// ref:DEC-distribution-canonical-wire ref:DEC-portable-seeded-generation\n[<Sealed; AllowNullLiteral>]\ntype MemoryNetwork(options: MemoryOptions) =\n    do\n        let valid condition reason = if not condition then Fail.raiseWith \"MemoryNetwork\" reason\n        valid (options.Loss >= 0.0 && options.Loss <= 1.0) \"invalid loss probability\"\n        valid (options.Duplicate >= 0.0 && options.Duplicate <= 1.0) \"invalid duplicate probability\"\n        valid (options.Delay >= 0.0 && options.Delay <= 4294967.0) \"invalid delay\"\n    let gate = obj ()\n    let mutable random = Random.seed options.Seed\n    let mutable generation = 0L\n    // Each registered address: its receiver and the generation it was registered at.\n    let nodes = Collections.Generic.Dictionary<string, (string -> byte[] -> unit) * int64>()\n    let mutable groups: string list list option = None\n    let trace = ResizeArray<MemoryEvent>()\n    let mutable closed = false\n    let cancel = new CancellationTokenSource()\n\n    static member DefaultOptions =\n        { Seed = BigInteger.Zero; Loss = 0.0; Duplicate = 0.0; Delay = 0.0; Record = false }\n\n    /// mem://name for a bare name.\n    static member AddressOf(name: string) =\n        if name.StartsWith \"mem://\" then name\n        elif String.IsNullOrEmpty name then Fail.raiseWith \"MemoryNetwork\" \"an empty node name\"\n        else \"mem://\" + name\n\n    member private this.Chance(probability: float) =\n        if probability <= 0.0 then false\n        else\n            let draw, next = Random.below (BigInteger(1 <<< 30)) random\n            random <- next\n            float draw < probability * float (1 <<< 30)\n\n    member private this.Remember(event: MemoryEvent) = if options.Record then trace.Add event\n\n    /// Register a receiver at an address.\n    member this.Register(address: string, receiver: string -> byte[] -> unit) : Result<unit, string> =\n        let address = MemoryNetwork.AddressOf address\n        lock gate (fun () ->\n            if closed then Error \"network_closed\"\n            elif nodes.ContainsKey address then Error \"already_registered\"\n            else\n                generation <- generation + 1L\n                nodes.[address] <- (receiver, generation)\n                Ok())\n\n    member this.Unregister(address: string) =\n        let address = MemoryNetwork.AddressOf address\n        lock gate (fun () -> nodes.Remove address |> ignore)\n\n    /// Send bytes from one registered address to another.\n    member this.Send(source: string, destination: string, bytes: byte[]) : Result<unit, string> =\n        let source = MemoryNetwork.AddressOf source\n        let destination = MemoryNetwork.AddressOf destination\n        let deliveries =\n            lock gate (fun () ->\n                let event = { Source = source; To = destination; Frame = bytes; Outcome = \"\"; DelaySlots = [] }\n                if closed || not (nodes.ContainsKey source) then Error \"not_node_owner\"\n                else\n                    match nodes.TryGetValue destination with\n                    | false, _ ->\n                        this.Remember { event with Outcome = \"unreachable\" }\n                        Error(\"unreachable \" + destination)\n                    | true, (_, registered) ->\n                        let reachable =\n                            match groups with\n                            | None -> true\n                            | Some gs -> gs |> List.exists (fun g -> List.contains source g && List.contains destination g)\n                        if not reachable then\n                            this.Remember { event with Outcome = \"partitioned\" }\n                            Ok []\n                        elif this.Chance options.Loss then\n                            this.Remember { event with Outcome = \"lost\" }\n                            Ok []\n                        else\n                            let copies = if this.Chance options.Duplicate then 2 else 1\n                            let slots =\n                                [ for _ in 1 .. copies ->\n                                      let slot, next = Random.below (BigInteger 1001) random\n                                      random <- next\n                                      int slot ]\n                            this.Remember { event with Outcome = \"sent\"; DelaySlots = slots }\n                            Ok [ for slot in slots -> int (ceil (float slot * options.Delay)), registered ])\n        match deliveries with\n        | Error e -> Error e\n        | Ok copies ->\n            for delay, registered in copies do\n                let deliver () =\n                    let receiver =\n                        lock gate (fun () ->\n                            match nodes.TryGetValue destination with\n                            | true, (r, g) when g = registered && not closed -> Some r\n                            | _ -> None)\n                    match receiver with\n                    | Some r -> (try r source bytes with _ -> ())\n                    | None -> ()\n                if delay <= 0 then ThreadPool.QueueUserWorkItem(fun _ -> deliver ()) |> ignore\n                else\n                    Task.Delay(delay, cancel.Token).ContinueWith(fun (t: Task) -> if not t.IsCanceled then deliver ())\n                    |> ignore\n            Ok()\n\n    /// Only nodes in one group reach each other until healed.\n    member this.Partition(groups': string list list) =\n        lock gate (fun () -> groups <- Some(groups' |> List.map (List.map MemoryNetwork.AddressOf)))\n\n    member this.Heal() = lock gate (fun () -> groups <- None)\n\n    /// Every frame sent, in order, when recording.\n    member this.Recorded() = lock gate (fun () -> trace |> Seq.map (fun e -> e.Frame) |> List.ofSeq)\n\n    member this.Trace() = lock gate (fun () -> List.ofSeq trace)\n\n    member this.Close() =\n        lock gate (fun () ->\n            closed <- true\n            nodes.Clear())\n        cancel.Cancel()\n\n    interface IDisposable with\n        member this.Dispose() = this.Close()\n"
dotnetSource "LawSpec.Runtime/Native.fs" = "/// The .NET types LawSpec values take at the native boundary, where a .NET\n/// type has no exact counterpart: exact fractions and decimals, single\n/// precision complex numbers, the two kinds of presence, and symbols. Every\n/// other LawSpec type maps to a .NET type directly (sbyte ... uint64, bigint,\n/// string, byte[], list, option, Rune). ref:DEC-fsharp-runtime-from-scratch\nnamespace LawSpec\n\nopen System.Numerics\n\n/// An exact fraction in lowest terms, with a positive denominator.\n[<CustomEquality; CustomComparison>]\ntype Rational =\n    private { N: BigInteger; D: BigInteger }\n    member this.Numerator = this.N\n    member this.Denominator = this.D\n    static member Create(numerator: BigInteger, denominator: BigInteger) =\n        if denominator.IsZero then invalidArg (nameof denominator) \"a rational's denominator is not zero\"\n        let g = BigInteger.GreatestCommonDivisor(numerator, denominator)\n        let s = if denominator.Sign < 0 then BigInteger.MinusOne else BigInteger.One\n        { N = s * numerator / g; D = BigInteger.Abs denominator / g }\n    override this.Equals other =\n        match other with\n        | :? Rational as r -> this.N = r.N && this.D = r.D\n        | _ -> false\n    override this.GetHashCode() = hash (this.N, this.D)\n    override this.ToString() = sprintf \"%O/%O\" this.N this.D\n    interface System.IComparable with\n        member this.CompareTo other =\n            match other with\n            | :? Rational as r -> compare (this.N * r.D) (r.N * this.D)\n            | _ -> invalidArg \"other\" \"a rational compares with a rational\"\n\n/// coefficient * 10 ^ exponent, exactly; 1.50 keeps its two places.\n[<Struct; CustomEquality; NoComparison>]\ntype ExactDecimal =\n    { Coefficient: BigInteger\n      Exponent: int }\n    override this.Equals other =\n        match other with\n        | :? ExactDecimal as d -> this.Coefficient = d.Coefficient && this.Exponent = d.Exponent\n        | _ -> false\n    override this.GetHashCode() = hash (this.Coefficient, this.Exponent)\n    override this.ToString() = sprintf \"%Oe%d\" this.Coefficient this.Exponent\n    /// Both decimals at the smaller exponent.\n    static member private Aligned(a: ExactDecimal, b: ExactDecimal) =\n        let e = min a.Exponent b.Exponent\n        let scale (d: ExactDecimal) = d.Coefficient * BigInteger.Pow(BigInteger 10, d.Exponent - e)\n        scale a, scale b, e\n    /// Exact sum, at the finer of the two scales.\n    static member (+)(a: ExactDecimal, b: ExactDecimal) =\n        let x, y, e = ExactDecimal.Aligned(a, b)\n        { Coefficient = x + y; Exponent = e }\n    /// Exact difference, at the finer of the two scales.\n    static member (-)(a: ExactDecimal, b: ExactDecimal) =\n        let x, y, e = ExactDecimal.Aligned(a, b)\n        { Coefficient = x - y; Exponent = e }\n    /// Exact product.\n    static member (*)(a: ExactDecimal, b: ExactDecimal) =\n        { Coefficient = a.Coefficient * b.Coefficient; Exponent = a.Exponent + b.Exponent }\n\n/// A complex number of two single precision floats (Complex128 is\n/// System.Numerics.Complex).\n[<Struct>]\ntype Complex64 = { Real: float32; Imaginary: float32 }\n\n/// A value that may be null, distinct from an absent Optional.\n[<RequireQualifiedAccess>]\ntype Nullable<'T> =\n    | Null\n    | Present of 'T\n\n/// A value that may be undefined, distinct from a null Nullable.\n[<RequireQualifiedAccess>]\ntype Optional<'T> =\n    | Undefined\n    | Present of 'T\n\n/// Either of two values; Left conventionally the failure.\n[<RequireQualifiedAccess>]\ntype Either<'L, 'R> =\n    | Left of left: 'L\n    | Right of right: 'R\n\n/// LawSpec's Null value.\ntype Null = | Null\n\n/// LawSpec's Undefined value.\ntype Undefined = | Undefined\n\n/// A symbol: equal only to itself.\n[<Sealed; AllowNullLiteral>]\ntype Symbol(identity: obj, description: string) =\n    new(description) = Symbol(obj (), description)\n    member _.Identity = identity\n    member _.Description = description\n    override _.Equals other =\n        match other with\n        | :? Symbol as s -> obj.ReferenceEquals(identity, s.Identity)\n        | _ -> false\n    override _.GetHashCode() = System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode identity\n    override _.ToString() = \"Symbol(\" + description + \")\"\n"
dotnetSource "LawSpec.Runtime/NetworkApi.fs" = "namespace LawSpec.Runtime\n\nopen System.Numerics\nopen System.Security.Cryptography\n\n/// The public network API (lawspec_network on BEAM): node options and\n/// identities, transports, in-memory networks and owned nodes.\n/// ref:DEC-distribution-canonical-wire\nmodule Network =\n    /// Options with no identity (a new one per node, or the configured one)\n    /// and the configured trust.\n    [<CompiledName(\"Options\")>]\n    let options () = NetworkConfig.empty\n\n    [<CompiledName(\"WithIdentity\")>]\n    let withIdentity (options: NetworkOptions) (identity: NodeIdentity) = { options with Identity = Some identity }\n\n    /// Trust exactly these fingerprints.\n    [<CompiledName(\"WithTrusted\")>]\n    let withTrusted (options: NetworkOptions) (fingerprints: string list) =\n        { options with Trusted = Some fingerprints; TrustGiven = true }\n\n    /// Trust any peer whose handshake verifies.\n    [<CompiledName(\"TrustOnFirstUse\")>]\n    let trustOnFirstUse (options: NetworkOptions) = { options with Trusted = None; TrustGiven = true }\n\n    [<CompiledName(\"IdentityFromSeed\")>]\n    let identityFromSeed (seed: byte[]) = NetworkRecords.identity (SecureNetwork.crypto ()) seed\n\n    [<CompiledName(\"NewIdentity\")>]\n    let newIdentity () = identityFromSeed (RandomNumberGenerator.GetBytes 32)\n\n    [<CompiledName(\"PublicKey\")>]\n    let publicKey (identity: NodeIdentity) = Array.copy identity.PublicKey\n\n    [<CompiledName(\"Fingerprint\")>]\n    let fingerprint (identity: NodeIdentity) = NetworkRecords.fingerprint (SecureNetwork.crypto ()) identity\n\n    [<CompiledName(\"Tcp\")>]\n    let tcp host port = Transports.tcp host port\n\n    [<CompiledName(\"Http\")>]\n    let http host port = Transports.http host port\n\n    [<CompiledName(\"Advertise\")>]\n    let advertise transport host = Transports.advertise transport host\n\n    /// Memory network options: seed, loss and duplicate chances, the most\n    /// delay in seconds, and whether to record frames.\n    [<CompiledName(\"MemoryOptions\")>]\n    let memoryOptions (seed: BigInteger) loss duplicate delay record : MemoryOptions =\n        { Seed = seed; Loss = loss; Duplicate = duplicate; Delay = delay; Record = record }\n\n    [<CompiledName(\"Memory\")>]\n    let memory (options: MemoryOptions) = new MemoryNetwork(options)\n\n    [<CompiledName(\"WithMemory\")>]\n    let withMemory (options: MemoryOptions) (body: MemoryNetwork -> 'a) : 'a =\n        use network = memory options\n        body network\n\n    [<CompiledName(\"CloseMemory\")>]\n    let closeMemory (network: MemoryNetwork) = network.Close()\n\n    [<CompiledName(\"MemoryTransport\")>]\n    let memoryTransport network name = Transports.memory network name\n\n    /// A memory transport without the secure layer, for tests only.\n    [<CompiledName(\"InsecureMemoryTransportForTests\")>]\n    let insecureMemoryTransportForTests network name = Transports.insecureMemoryForTests network name\n\n    [<CompiledName(\"Partition\")>]\n    let partition (network: MemoryNetwork) (groups: string list list) = network.Partition groups\n\n    [<CompiledName(\"Heal\")>]\n    let heal (network: MemoryNetwork) = network.Heal()\n\n    [<CompiledName(\"Recorded\")>]\n    let recorded (network: MemoryNetwork) = network.Recorded()\n\n    [<CompiledName(\"Open\")>]\n    let openNode (transport: Transport) (options: NetworkOptions) =\n        try new Node(transport, options)\n        with :? LawSpecException as e when e.Code <> \"Network\" && e.Code <> \"SecureNetworkNotAvailable\" ->\n            Fail.raiseWith \"Network\" e.Message\n\n    [<CompiledName(\"Close\")>]\n    let close (node: Node) = node.Close()\n\n    [<CompiledName(\"WithNode\")>]\n    let withNode (transport: Transport) (options: NetworkOptions) (body: Node -> 'a) : 'a =\n        let node = openNode transport options\n        try body node finally close node\n\n    [<CompiledName(\"Address\")>]\n    let address (node: Node) = node.Address\n\n    [<CompiledName(\"NodeFingerprint\")>]\n    let nodeFingerprint (node: Node) = node.Identity\n\n    /// The wire encodings, in hexadecimal, of count values a descriptor text\n    /// draws from a seed at a size (the distribution suite's vectors).\n    [<CompiledName(\"WireEncoded\")>]\n    let wireEncoded (text: string) (seed: BigInteger) (size: int) (count: int) : string list =\n        let table, d = Descriptors.fromText text\n        let mutable state = Random.seed seed\n        [ for _ in 1 .. max 0 count ->\n              let v, next = Descriptors.generate d table state size\n              state <- next\n              Wire.hex (Descriptors.encode d v table) ]\n\n    /// Whether count values a descriptor text draws decode to themselves.\n    [<CompiledName(\"WireRoundTrips\")>]\n    let wireRoundTrips (text: string) (seed: BigInteger) (size: int) (count: int) : bool =\n        let table, d = Descriptors.fromText text\n        let mutable state = Random.seed seed\n        Seq.forall id [ for _ in 1 .. max 0 count ->\n                            let v, next = Descriptors.generate d table state size\n                            state <- next\n                            Descriptors.render (Descriptors.decode d (Descriptors.encode d v table) table) = Descriptors.render v ]\n\n    /// Whether this runtime's secure handshake gives a cross-target vector's\n    /// bytes: the hello and welcome hashes, the session key and a sealed frame\n    /// (all in hexadecimal) from the two identities' and the KEM key's seeds.\n    [<CompiledName(\"HandshakeVector\")>]\n    let handshakeVector (initiatorSeed: string) (responderSeed: string) (kemSeed: string) (session: string) (initiator: string) (responder: string)\n                        (ciphertext: string) (nonce: string) (frame: string) (helloHash: string) (welcomeHash: string) (key: string) (record: string) : bool =\n        let crypto = SecureNetwork.crypto ()\n        let bytes (text: string) = System.Convert.FromHexString text\n        try\n            let first = NetworkRecords.identity crypto (bytes initiatorSeed)\n            let second = NetworkRecords.identity crypto (bytes responderSeed)\n            let kemPublic, kemSecret = crypto.MlKemKeypair(bytes kemSeed)\n            let hello = NetworkRecords.hello (bytes session) initiator first.PublicKey kemPublic\n            let welcome = NetworkRecords.welcome crypto (bytes session) responder second.PublicKey (bytes ciphertext) hello\n            let derived = NetworkRecords.key crypto (crypto.MlKemDecapsulate(kemSecret, bytes ciphertext)) hello welcome\n            let sealedRecord = NetworkRecords.sealWith crypto derived (bytes session) 0 (bytes frame) (bytes nonce)\n            let sealedBytes = Array.append (bytes nonce) (crypto.AesGcmEncrypt(derived, bytes nonce, bytes frame, Array.concat [ System.Text.Encoding.ASCII.GetBytes \"lawspec-frame-v1\"; bytes session; [| 0uy |] ]))\n            Wire.hex (crypto.Sha3_256 hello) = helloHash\n            && Wire.hex (crypto.Sha3_256 welcome) = welcomeHash\n            && Wire.hex derived = key\n            && Wire.hex sealedRecord = record\n            && NetworkRecords.openSealed crypto derived (bytes session) 0 sealedBytes = Some(bytes frame)\n        with _ -> false\n"
dotnetSource "LawSpec.Runtime/NetworkCrypto.fs" = "/// The secure transport's version 1 records (\"LS\" 1): a node's ML-DSA-65\n/// identity, the signed hello and welcome of the ML-KEM-768 handshake, the\n/// session key derived with SHAKE256, and AES-256-GCM sealed frames. The\n/// bytes are the same as every other target's, so nodes interoperate.\n/// ref:DEC-distribution-canonical-wire ref:DEC-typed-core-boundary\nmodule LawSpec.Runtime.NetworkCrypto\n\nopen System.Text\n\n/// A node's identity: its signing seed and public key.\ntype Identity =\n    private { Seed: byte[]; PublicKey: byte[] }\n    member this.Public = this.PublicKey\n\nlet private fail code : 'a = Fail.raiseWith code \"\"\n\n/// The identity of a 32-byte seed.\n[<CompiledName(\"Identity\")>]\nlet identity (seed: byte[]) =\n    if isNull seed || seed.Length <> 32 then fail \"InvalidNodeIdentity\"\n    { Seed = Array.copy seed; PublicKey = Crypto.mldsaPublic seed }\n\n[<CompiledName(\"Public\")>]\nlet publicKey (identity: Identity) = identity.PublicKey\n\n/// The lowercase hex SHA3-256 of a node's public key.\n[<CompiledName(\"Fingerprint\")>]\nlet fingerprint (identity: Identity) = (System.Convert.ToHexString(Crypto.sha3 identity.PublicKey)).ToLowerInvariant()\n\n[<CompiledName(\"Sign\")>]\nlet sign (identity: Identity) (bytes: byte[]) = Crypto.mldsaSign identity.Seed bytes\n\n[<CompiledName(\"Verify\")>]\nlet verify (publicKey: byte[]) (bytes: byte[]) (signature: byte[]) = Crypto.mldsaVerify publicKey bytes signature\n\nlet private bytesType = Descriptors.Forms [ Descriptors.Atom \"bytes\" ]\n\n/// Byte strings as consecutive length-prefixed wire fields.\n[<CompiledName(\"Fields\")>]\nlet fields (values: byte[] list) : byte[] =\n    values |> List.map (fun v -> Descriptors.encode bytesType (Bytes v) Map.empty) |> Array.concat\n\nlet private readFields (count: int) (bytes: byte[]) (start: int) =\n    let mutable position = start\n    let values =\n        [ for _ in 1 .. count ->\n              match Descriptors.decodePrefix bytesType bytes position Map.empty with\n              | Bytes b, next ->\n                  position <- next\n                  b\n              | _ -> fail \"InvalidSecureRecord\" ]\n    values, position\n\n/// A handshake hello: session, address, public key and KEM public key.\n[<CompiledName(\"Hello\")>]\nlet hello (session: byte[]) (address: byte[]) (publicKey: byte[]) (kem: byte[]) = fields [ session; address; publicKey; kem ]\n\n/// A handshake welcome, bound to the hello it answers.\n[<CompiledName(\"Welcome\")>]\nlet welcome (session: byte[]) (address: byte[]) (publicKey: byte[]) (ciphertext: byte[]) (helloBytes: byte[]) =\n    fields [ session; address; publicKey; ciphertext; Crypto.sha3 helloBytes ]\n\n/// The session key of a shared secret and the handshake that agreed it.\n[<CompiledName(\"Key\")>]\nlet key (shared: byte[]) (helloBytes: byte[]) (welcomeBytes: byte[]) =\n    Crypto.shake (Array.concat [ shared; Encoding.ASCII.GetBytes \"lawspec-session-v1\"; Crypto.sha3 helloBytes; Crypto.sha3 welcomeBytes ]) 32\n\n/// A signed handshake record of a kind (1 hello, 2 welcome).\n[<CompiledName(\"Record\")>]\nlet record (kind: byte) (body: byte[]) (signature: byte[]) =\n    Array.concat [ [| byte 'L'; byte 'S'; 1uy; kind |]; body; fields [ signature ] ]\n\n/// A record as read off the wire.\ntype Read =\n    /// A hello (1) or welcome (2): its fields, the signed body and the signature.\n    | Handshake of kind: int * values: byte[] list * body: byte[] * signature: byte[]\n    /// A sealed frame: session, direction and sealed bytes.\n    | Frame of session: byte[] * direction: byte * sealedBytes: byte[]\n\n/// Read a version 1 record.\n[<CompiledName(\"Read\")>]\nlet read (bytes: byte[]) : Read =\n    if bytes.Length < 4 || bytes.[0] <> byte 'L' || bytes.[1] <> byte 'S' || bytes.[2] <> 1uy then fail \"InvalidSecureRecord\"\n    match bytes.[3] with\n    | 1uy | 2uy as kind ->\n        let count = if kind = 1uy then 4 else 5\n        let values, bodyEnd = readFields count bytes 4\n        let signature, finish = readFields 1 bytes bodyEnd\n        if finish <> bytes.Length then fail \"InvalidSecureRecord\"\n        Handshake(int kind, values, bytes.[4 .. bodyEnd - 1], List.head signature)\n    | 3uy ->\n        let session, next = readFields 1 bytes 4\n        if next >= bytes.Length then fail \"InvalidSecureRecord\"\n        let direction = bytes.[next]\n        let sealedField, finish = readFields 1 bytes (next + 1)\n        if finish <> bytes.Length then fail \"InvalidSecureRecord\"\n        Frame(List.head session, direction, List.head sealedField)\n    | _ -> fail \"InvalidSecureRecord\"\n\nlet private associated (session: byte[]) (direction: byte) =\n    Array.concat [ Encoding.ASCII.GetBytes \"lawspec-frame-v1\"; session; [| direction |] ]\n\n/// A frame sealed with a given nonce.\n[<CompiledName(\"SealWith\")>]\nlet sealWith (key: byte[]) (session: byte[]) (direction: byte) (frame: byte[]) (nonce: byte[]) =\n    let sealedBytes = Array.append nonce (Crypto.aes256GcmEncrypt key nonce frame (associated session direction))\n    Array.concat [ [| byte 'L'; byte 'S'; 1uy; 3uy |]; fields [ session ]; [| direction |]; fields [ sealedBytes ] ]\n\n/// A frame sealed with a fresh nonce.\n[<CompiledName(\"Seal\")>]\nlet seal (key: byte[]) (session: byte[]) (direction: byte) (frame: byte[]) = sealWith key session direction frame (Crypto.randomBytes 12)\n\n/// Open a sealed frame's bytes, or None.\n[<CompiledName(\"Open\")>]\nlet openFrame (key: byte[]) (session: byte[]) (direction: byte) (sealedBytes: byte[]) =\n    Crypto.unseal key sealedBytes (associated session direction)\n"
dotnetSource "LawSpec.Runtime/Node.fs" = "namespace LawSpec.Runtime\n\nopen System\nopen System.Security.Cryptography\nopen System.Threading\nopen System.Threading.Tasks\nopen LawSpec.Runtime.Wire\n\n/// Something registered at a node under a name: a handler, whose answer the\n/// node sends as the reply, or a receiver that answers later with Reply.\ntype Entity =\n    | Handler of (Frame -> int * byte[])\n    | Receiver of (Frame -> unit)\n\ntype private Seen =\n    { mutable Response: byte[] option\n      Entity: string\n      Fingerprint: byte[] }\n\ntype private Arrival =\n    | Resend of byte[]\n    | Ignore\n    | Missing\n    | Dispatch of Entity\n\ntype private Pending =\n    { Address: string\n      Peer: string\n      Frame: Frame\n      Deadline: DateTime\n      Respond: Result<int * byte[], string> -> unit\n      mutable Timer: Timer }\n\n/// A node: named entities reached by frames, and reliable request and reply\n/// over a transport. Requests are deduplicated by sender and identity, even\n/// while their handler runs, and retried until answered or out of time.\n/// Handlers run in tasks the node owns. Status codes: 0 ok, 1 failed,\n/// 2 stopped, 3 rejected.\n/// ref:DEC-distribution-canonical-wire ref:DEC-async-native-tasks\n[<Sealed; AllowNullLiteral>]\ntype Node(transport: Transport, options: NetworkOptions) as this =\n    let gate = obj ()\n    let entities = Collections.Generic.Dictionary<string, Entity>()\n    let seen = Collections.Generic.Dictionary<string * uint64, Seen>()\n    let pending = Collections.Generic.Dictionary<uint64, Pending>()\n    let jobs = Collections.Concurrent.ConcurrentDictionary<int, Task>()\n    let services = Collections.Concurrent.ConcurrentBag<IDisposable>()\n    let mutable closed = false\n    let mutable nextId =\n        match options.FirstId with\n        | Some id -> id\n        | None -> (BitConverter.ToUInt64(RandomNumberGenerator.GetBytes 8, 0) &&& ((1UL <<< 61) - 1UL)) + 1UL\n    let mutable secure: SecureLayer = Unchecked.defaultof<_>\n    let mutable raw: IPacketTransport = Unchecked.defaultof<_>\n    let fail reason : 'a = Fail.raiseWith \"Network\" reason\n\n    let fingerprint (frame: Frame) =\n        SHA256.HashData(encodeFrame frame.Kind frame.To frame.Source frame.Id frame.Payload)\n\n    do\n        match transport with\n        | Memory(_, _, true) -> raw <- Transports.open' transport (fun _ bytes -> this.Packet bytes)\n        | _ ->\n            let layer = new SecureLayer(SecureNetwork.crypto (), transport, options, fun _ bytes -> this.Packet bytes)\n            layer.Start()\n            secure <- layer\n\n    /// The node's address: mem://name, tcp://host:port or http://host:port.\n    member _.Address = if isNull (box secure) then raw.Address else secure.Address\n\n    /// The fingerprint of the node's identity (secure nodes only).\n    member _.Identity = if isNull (box secure) then fail \"insecure_node\" else secure.Fingerprint\n\n    member private _.Wire(peer: string, bytes: byte[]) =\n        if isNull (box secure) then raw.Send(peer, bytes) else secure.Send(peer, bytes)\n\n    member private this.Transmit(frame: Frame) =\n        let peer, name = splitAddress frame.To\n        let source = if frame.Source = \"\" then this.Address else frame.Source\n        this.Wire(peer, encodeFrame frame.Kind name source frame.Id frame.Payload)\n\n    member private this.Validate(frame: Frame) =\n        try\n            splitAddress frame.To |> ignore\n            encodeFrame frame.Kind \"\" frame.Source frame.Id frame.Payload |> ignore\n        with _ -> fail \"invalid_frame\"\n\n    member private this.SendReply(source: string, identity: uint64, payload: byte[]) =\n        try this.Transmit { Kind = \"reply\"; To = source + \"/\"; Source = \"\"; Id = identity; Payload = payload } |> ignore\n        with _ -> ()\n\n    member private this.Answer(key: string * uint64, status: int, body: byte[]) =\n        let payload = Array.append [| byte status |] body\n        let send =\n            lock gate (fun () ->\n                match seen.TryGetValue key with\n                | true, entry when entry.Response.IsNone ->\n                    entry.Response <- Some payload\n                    true\n                | _ -> false)\n        if send then this.SendReply(fst key, snd key, payload)\n\n    member private this.Finish(identity: uint64, result: Result<int * byte[], string> option) =\n        let found =\n            lock gate (fun () ->\n                match pending.TryGetValue identity with\n                | true, p ->\n                    pending.Remove identity |> ignore\n                    if not (isNull p.Timer) then p.Timer.Dispose()\n                    Some p\n                | _ -> None)\n        match found, result with\n        | Some p, Some r -> p.Respond r\n        | _ -> ()\n\n    /// A packet from the transport.\n    member internal this.Packet(bytes: byte[]) =\n        match readFrame bytes with\n        | Some frame -> (try this.Arrive frame with _ -> ())\n        | None -> ()\n\n    member private this.Arrive(frame: Frame) =\n        if frame.Kind = \"reply\" then\n            if frame.Payload.Length >= 1 then\n                let matches =\n                    lock gate (fun () ->\n                        match pending.TryGetValue frame.Id with\n                        | true, p -> p.Peer = frame.Source\n                        | _ -> false)\n                if matches then this.Finish(frame.Id, Some(Ok(int frame.Payload.[0], frame.Payload.[1..])))\n        else\n            let key = frame.Source, frame.Id\n            let action =\n                lock gate (fun () ->\n                    match seen.TryGetValue key with\n                    | true, entry when frame.Id <> 0UL ->\n                        if fingerprint frame <> entry.Fingerprint then\n                            Resend(Array.append [| 3uy |] (Text.Encoding.UTF8.GetBytes \"a request identity was reused for different content\"))\n                        else\n                            match entry.Response with\n                            | Some response -> Resend response\n                            | None -> Ignore\n                    | _ ->\n                        match entities.TryGetValue frame.To with\n                        | false, _ ->\n                            if frame.Id = 0UL then Ignore\n                            else\n                                seen.[key] <- { Response = None; Entity = frame.To; Fingerprint = fingerprint frame }\n                                Missing\n                        | true, entity ->\n                            if frame.Id <> 0UL then\n                                seen.[key] <- { Response = None; Entity = frame.To; Fingerprint = fingerprint frame }\n                            Dispatch entity)\n            match action with\n            | Resend payload -> this.SendReply(frame.Source, frame.Id, payload)\n            | Ignore -> ()\n            | Missing -> this.Answer(key, 3, Text.Encoding.UTF8.GetBytes(\"nothing is registered as \" + frame.To))\n            | Dispatch(Receiver receive) -> receive frame\n            | Dispatch(Handler handle) ->\n                let job =\n                    Task.Run(fun () ->\n                        let status, body =\n                            try\n                                let status, body = handle frame\n                                if status < 0 || status > 255 then 1, Text.Encoding.UTF8.GetBytes \"invalid reply\"\n                                else status, body\n                            with e -> 1, Text.Encoding.UTF8.GetBytes e.Message\n                        if frame.Id <> 0UL then this.Answer(key, status, body))\n                jobs.[job.Id] <- job\n                job.ContinueWith(fun (t: Task) -> jobs.TryRemove(t.Id) |> ignore) |> ignore\n\n    member private this.Register(name: string, entity: Entity) =\n        if String.IsNullOrEmpty name || name.Contains '/' then fail \"invalid_entity_name\"\n        lock gate (fun () ->\n            if closed then fail \"node_closed\"\n            if entities.ContainsKey name then fail (\"already_registered \" + name)\n            entities.[name] <- entity)\n        this.Address + \"/\" + name\n\n    /// Serve requests to a name with a handler of each frame; its answer is\n    /// the reply's status and body. The entity's address.\n    member this.RegisterHandler(name: string, handler: Frame -> int * byte[]) = this.Register(name, Handler handler)\n\n    /// Deliver each frame for a name to a receiver, which answers with Reply.\n    member this.RegisterReceiver(name: string, receiver: Frame -> unit) = this.Register(name, Receiver receiver)\n\n    /// A service the node closes when it closes.\n    member internal this.Adopt(service: IDisposable) = services.Add service\n\n    /// Remove a name; requests to it still waiting are answered as stopped.\n    member this.Unregister(name: string) =\n        let waiting =\n            lock gate (fun () ->\n                if entities.Remove name then\n                    [ for KeyValue(key, entry) in seen do if entry.Entity = name && entry.Response.IsNone then yield key ]\n                else [])\n        for key in waiting do this.Answer(key, 2, Text.Encoding.UTF8.GetBytes \"the receiving entity has stopped\")\n\n    /// Send a frame of a kind to an address, with no reply.\n    member this.Send(address: string, kind: string, payload: byte[]) =\n        let frame = frameTo address kind payload\n        this.Validate frame\n        this.Transmit frame |> ignore\n\n    /// Send a frame as given (an endpoint's protocol frames).\n    member this.Forward(frame: Frame) =\n        this.Validate frame\n        this.Transmit frame |> ignore\n\n    /// Request: retried every 100 ms until a reply or the timeout (ms). The\n    /// callback gets the reply's status and body, or the failure. Returns\n    /// the request's identity.\n    member this.RequestAsync(address: string, kind: string, payload: byte[], timeout: int, respond: Result<int * byte[], string> -> unit) : uint64 =\n        if timeout < 0 then fail \"invalid_timeout\"\n        let peer, _ = splitAddress address\n        let identity, frame =\n            lock gate (fun () ->\n                if closed then fail \"node_closed\"\n                let identity = nextId\n                nextId <- nextId + 1UL\n                let frame = { Kind = kind; To = address; Source = \"\"; Id = identity; Payload = payload }\n                this.Validate frame\n                let p = { Address = address; Peer = peer; Frame = frame; Deadline = DateTime.UtcNow.AddMilliseconds(float timeout); Respond = respond; Timer = null }\n                pending.[identity] <- p\n                let period = max 1 (min 100 timeout)\n                p.Timer <-\n                    new Timer((fun _ ->\n                        let resend =\n                            lock gate (fun () ->\n                                match pending.TryGetValue identity with\n                                | true, q when DateTime.UtcNow >= q.Deadline -> Some false\n                                | true, _ -> Some true\n                                | _ -> None)\n                        match resend with\n                        | Some true -> this.Transmit frame |> ignore\n                        | Some false -> this.Finish(identity, Some(Error(\"unreachable \" + address)))\n                        | None -> ()), null, period, period)\n                identity, frame)\n        this.Transmit frame |> ignore\n        identity\n\n    /// Request and wait for the reply's status and body.\n    member this.Request(address: string, kind: string, payload: byte[], timeout: int) : int * byte[] =\n        let result = TaskCompletionSource<Result<int * byte[], string>>(TaskCreationOptions.RunContinuationsAsynchronously)\n        this.RequestAsync(address, kind, payload, timeout, result.SetResult >> ignore) |> ignore\n        match result.Task.Result with\n        | Ok reply -> reply\n        | Error reason -> fail reason\n\n    /// Forget a request; its callback is not called.\n    member this.Cancel(identity: uint64) = this.Finish(identity, None)\n\n    /// Answer a request a receiver was given.\n    member this.Reply(source: string, identity: uint64, status: int, body: byte[]) =\n        if status < 0 || status > 255 then fail \"invalid_reply\"\n        if identity <> 0UL then this.Answer((source, identity), status, body)\n\n    /// Close the node: its services, its waiting requests and its transport.\n    member this.Close() =\n        let waiting =\n            lock gate (fun () ->\n                if closed then []\n                else\n                    closed <- true\n                    let all = List.ofSeq pending.Values\n                    pending.Clear()\n                    all)\n        for service in services do (try service.Dispose() with _ -> ())\n        for p in waiting do\n            if not (isNull p.Timer) then p.Timer.Dispose()\n            p.Respond(Error \"node_closed\")\n        (try Task.WaitAll(Array.ofSeq jobs.Values, 5000) |> ignore with _ -> ())\n        if isNull (box secure) then raw.Dispose() else secure.Close()\n\n    interface IDisposable with\n        member this.Dispose() = this.Close()\n"
dotnetSource "LawSpec.Runtime/Policy.fs" = "/// Workflow policies as values: retry strategies and their delays, jitter\n/// drawn from an explicit SplitMix64 state, the gates a stage passes\n/// (breakers, rate limits, bulkheads) and the logical failures a stage gives.\n/// Durations are whole microseconds. The policy's random stream is separate\n/// from the Random ability's. ref:DEC-domain-modeling-primitives ref:splitmix\n/// ref:DEC-typed-core-boundary\nmodule LawSpec.Runtime.Policy\n\nopen System.Numerics\n\n/// How long to wait before each retry.\ntype Strategy =\n    | Immediate\n    | Fixed of delay: int64\n    | Linear of delay: int64 * step: int64\n    | Exponential of delay: int64 * factor: int64 * cap: int64 option\n    | Fibonacci of delay: int64\n    /// A checked definition decides: attempt (Int), error, previous delay\n    /// (a Duration) to a RetryDecision.\n    | Custom of decide: (Value -> Value -> Value -> Value)\n\n/// How a delay is randomized.\ntype Jitter =\n    | NoJitter\n    | FullJitter\n    | EqualJitter\n    | DecorrelatedJitter\n\n/// Attempts count the first try; zero attempts retries without a bound.\ntype Retry =\n    { Strategy: Strategy\n      Attempts: int64\n      Jitter: Jitter\n      /// Whether an error is worth retrying (a portable Bool).\n      When: (Value -> Value) option }\n\ntype GateKind =\n    | Breaker\n    | Limit\n    | Bulkhead\n\n/// How long a stage may wait at a gate that answers WaitFor.\ntype Wait =\n    | NoWait\n    | Forever\n    | Within of int64\n\n/// A gate: its state starts at a time, admits at a time (giving the next\n/// state and a Gate decision), and may record how an admitted call ended.\n/// Times are portable Ints, the outcome a portable Bool.\ntype Gate =\n    { Kind: GateKind\n      Start: Value -> Value\n      Admit: Value -> Value -> Value\n      Finish: (Value -> Value -> Value -> Value) option\n      Wait: Wait }\n\n/// A stage's policies, as a definition with a policy declares them.\ntype StagePolicy =\n    { Key: string\n      Stage: string\n      Retry: Retry option\n      Timeout: int64 option\n      Gates: Gate list\n      Cache: int64 option\n      Compensate: (Value -> Value) option\n      Wraps: bool\n      /// A further attempt starts after the delay, up to most in all.\n      Hedge: (int64 * int64) option }\n\nlet private fail code detail : 'a = Fail.raiseWith code detail\n\nlet rec private power (b: int64) (n: int64) : int64 =\n    if n = 0L then 1L\n    elif n % 2L = 0L then power (b * b) (n / 2L)\n    else b * power (b * b) (n / 2L)\n\nlet rec private fibonacci (n: int64) (a: int64) (b: int64) = if n <= 1L then a else fibonacci (n - 1L) b (a + b)\n\n/// The delay before an attempt (from the second) of a strategy.\n[<CompiledName(\"RetryDelay\")>]\nlet retryDelay (strategy: Strategy) (attempt: int64) : int64 =\n    if attempt < 2L then fail \"InvalidRetryAttempt\" (string attempt)\n    match strategy with\n    | Immediate -> 0L\n    | Fixed delay -> delay\n    | Linear(delay, step) -> delay + step * (attempt - 2L)\n    | Exponential(delay, factor, cap) ->\n        let value = delay * power factor (attempt - 2L)\n        match cap with\n        | Some c -> min value c\n        | None -> value\n    | Fibonacci delay -> delay * fibonacci (attempt - 1L) 1L 1L\n    | Custom _ -> fail \"CustomRetryDelay\" \"a custom strategy decides its own delays\"\n\nlet private below (bound: int64) state =\n    let n, next = Random.below (BigInteger bound) state\n    int64 n, next\n\n/// A jittered delay and the next random state.\n[<CompiledName(\"Jittered\")>]\nlet jitter (kind: Jitter) (delay: int64) (previous: int64) (baseDelay: int64) (state: Random.Seed) : int64 * Random.Seed =\n    match kind with\n    | NoJitter -> delay, state\n    | FullJitter -> below (delay + 1L) state\n    | EqualJitter ->\n        let half = delay / 2L\n        let r, next = below (delay - half + 1L) state\n        half + r, next\n    | DecorrelatedJitter ->\n        let high = max baseDelay (previous * 3L)\n        let r, next = below (high - baseDelay + 1L) state\n        min delay (baseDelay + r), next\n\n/// A custom strategy's RetryDecision: Some delay to wait, None to stop.\n[<CompiledName(\"RetryDecision\")>]\nlet retryDecision (decision: Value) : int64 option =\n    match decision with\n    | Data(\"lawspec.time::type::RetryDecision::RetryAfter\", [ Data(_, [ Int delay ]) ]) -> Some(int64 delay)\n    | Data(\"lawspec.time::type::RetryDecision::Stop\", []) -> None\n    | other -> fail \"InvalidRetryDecision\" (sprintf \"%A\" other)\n\n/// Whether a stage's result is a failure (a Left).\n[<CompiledName(\"Failed\")>]\nlet failed (result: Value) =\n    match result with\n    | Data(\"Either::Left\", [ _ ]) -> true\n    | _ -> false\n\n/// A stage's own failure: TimedOut, RateLimited, CircuitOpen or Saturated.\n[<CompiledName(\"StageFailure\")>]\nlet stageFailure (kind: string) : Value =\n    match kind with\n    | \"TimedOut\" | \"RateLimited\" | \"CircuitOpen\" | \"Saturated\" ->\n        Data(\"Either::Left\", [ Data(\"lawspec.resilience::type::StageFailure::\" + kind, []) ])\n    | _ -> fail \"UnknownStageFailure\" kind\n\n// ---------------------------------------------------------------------------\n// Builders, as generated code writes a policy\n\n[<CompiledName(\"Immediate\")>]\nlet immediate () = Immediate\n\n[<CompiledName(\"Fixed\")>]\nlet fixedDelay (delay: int64) = Fixed delay\n\n[<CompiledName(\"Linear\")>]\nlet linear (delay: int64) (step: int64) = Linear(delay, step)\n\n[<CompiledName(\"Exponential\")>]\nlet exponential (delay: int64) (factor: int64) (cap: int64 option) = Exponential(delay, factor, cap)\n\n[<CompiledName(\"Fibonacci\")>]\nlet fibonacciDelay (delay: int64) = Fibonacci delay\n\n[<CompiledName(\"Custom\")>]\nlet custom (decide: Value -> Value -> Value -> Value) = Custom decide\n\n/// A jitter by name: none, full, equal or decorrelated.\n[<CompiledName(\"JitterOf\")>]\nlet jitterOf (name: string) =\n    match name with\n    | \"none\" -> NoJitter\n    | \"full\" -> FullJitter\n    | \"equal\" -> EqualJitter\n    | \"decorrelated\" -> DecorrelatedJitter\n    | _ -> fail \"UnknownJitter\" name\n\n[<CompiledName(\"Retry\")>]\nlet retry (strategy: Strategy) (attempts: int64) (jitter: Jitter) (condition: (Value -> Value) option) =\n    { Strategy = strategy; Attempts = attempts; Jitter = jitter; When = condition }\n\n[<CompiledName(\"NoWait\")>]\nlet noWait () = NoWait\n\n[<CompiledName(\"Forever\")>]\nlet forever () = Forever\n\n[<CompiledName(\"Within\")>]\nlet within (micros: int64) = Within micros\n\n[<CompiledName(\"Breaker\")>]\nlet breaker (start: Value -> Value) (admit: Value -> Value -> Value) (finish: Value -> Value -> Value -> Value) =\n    { Kind = Breaker; Start = start; Admit = admit; Finish = Some finish; Wait = NoWait }\n\n[<CompiledName(\"Limit\")>]\nlet limit (start: Value -> Value) (admit: Value -> Value -> Value) (wait: Wait) =\n    { Kind = Limit; Start = start; Admit = admit; Finish = None; Wait = wait }\n\n[<CompiledName(\"Bulkhead\")>]\nlet bulkhead (start: Value -> Value) (admit: Value -> Value -> Value) (finish: Value -> Value -> Value -> Value) (wait: Wait) =\n    { Kind = Bulkhead; Start = start; Admit = admit; Finish = Some finish; Wait = wait }\n\n/// A stage's policy.\n[<CompiledName(\"Stage\")>]\nlet stage (key: string) (stageName: string) (retry: Retry option) (timeout: int64 option) (gates: Gate list)\n          (cache: int64 option) (compensate: (Value -> Value) option) (wraps: bool) (hedge: (int64 * int64) option) =\n    { Key = key; Stage = stageName; Retry = retry; Timeout = timeout; Gates = gates; Cache = cache\n      Compensate = compensate; Wraps = wraps; Hedge = hedge }\n"
dotnetSource "LawSpec.Runtime/Portable.fs" = "/// LawSpec's portable equality, hash and order over native .NET values. The\n/// generated records and unions use it, so a native value orders as its\n/// portable value does on every target: text by code point, constructors by\n/// their identities, fields left to right. ref:DEC-portable-exact-arithmetic\n/// ref:DEC-idiomatic-generated-types\nmodule LawSpec.Runtime.Portable\n\nopen System\nopen System.Collections\nopen System.Numerics\nopen System.Text\nopen LawSpec\n\nlet private noOrder (a: obj) = Fail.raiseWith \"NoPortableOrder\" (if isNull a then \"null\" else a.GetType().Name)\n\n/// Equality: structural, with floats compared by their bits (so it is\n/// reflexive, as .NET collections require).\n[<CompiledName(\"Equal\")>]\nlet rec equal (a: obj) (b: obj) : bool =\n    match a, b with\n    | null, null -> true\n    | null, _ | _, null -> false\n    | (:? float as x), (:? float as y) -> BitConverter.DoubleToInt64Bits x = BitConverter.DoubleToInt64Bits y\n    | (:? float32 as x), (:? float32 as y) -> BitConverter.SingleToInt32Bits x = BitConverter.SingleToInt32Bits y\n    | (:? string as x), (:? string as y) -> String.Equals(x, y, StringComparison.Ordinal)\n    | (:? (byte[]) as x), (:? (byte[]) as y) -> ReadOnlySpan<byte>(x).SequenceEqual(ReadOnlySpan<byte>(y))\n    | (:? IStructuralEquatable as x), _ when not (a :? string) -> x.Equals(b, StructuralComparisons.StructuralEqualityComparer)\n    | _ -> a.Equals b\n\n/// A hash consistent with equal.\n[<CompiledName(\"Hash\")>]\nlet rec hash (a: obj) : int =\n    match a with\n    | null -> 0\n    | :? float as x -> BitConverter.DoubleToInt64Bits(x).GetHashCode()\n    | :? float32 as x -> BitConverter.SingleToInt32Bits(x)\n    | :? (byte[]) as x ->\n        let mutable h = 17\n        for b in x do h <- h * 31 + int b\n        h\n    | :? IStructuralEquatable as x -> x.GetHashCode(StructuralComparisons.StructuralEqualityComparer)\n    | _ -> a.GetHashCode()\n\n/// Generated records and unions implement this: their CompareTo is the\n/// portable order.\ntype IPortable =\n    inherit IComparable\n\nlet private unionCache = Collections.Concurrent.ConcurrentDictionary<Type, (obj -> int) * (obj -> obj[])>()\n\nlet private unionParts (t: Type) =\n    unionCache.GetOrAdd(t, fun t ->\n        let tag = Reflection.FSharpValue.PreComputeUnionTagReader(t)\n        let readers =\n            Reflection.FSharpType.GetUnionCases(t)\n            |> Array.map (fun c -> Reflection.FSharpValue.PreComputeUnionReader(c))\n        tag, (fun v -> readers.[tag v] v))\n\n/// Text by code point, for a .NET collection that takes a comparer\n/// (StringComparer.Ordinal orders by UTF-16 unit, which differs for\n/// characters outside the Basic Multilingual Plane).\n[<CompiledName(\"TextOrder\")>]\nlet textOrder: Collections.Generic.IComparer<string> =\n    { new Collections.Generic.IComparer<string> with\n        member _.Compare(a, b) = Scalar.compareText a b }\n\nlet private orderCache = Collections.Concurrent.ConcurrentDictionary<Type, bool>()\n\n/// Whether F#'s own comparison of a type can disagree with the portable\n/// order: it holds text somewhere F# compares (ordinally, by UTF-16 unit)\n/// rather than a generated type, which compares portably.\n[<CompiledName(\"Reorders\")>]\nlet rec reorders (t: Type) : bool =\n    match orderCache.TryGetValue t with\n    | true, known -> known\n    | _ ->\n        let result =\n            if t = typeof<string> then true\n            elif typeof<IPortable>.IsAssignableFrom t then false\n            elif t.IsArray then reorders (t.GetElementType())\n            elif t.IsGenericType then t.GetGenericArguments() |> Array.exists reorders\n            else false\n        orderCache.[t] <- result\n        result\n\nlet private setType = typedefof<Set<int>>\nlet private mapType = typedefof<Map<int, int>>\n\n/// The portable order of two native values of one type.\n[<CompiledName(\"Compare\")>]\nlet rec compare (a: obj) (b: obj) : int =\n    match a, b with\n    | null, null -> 0\n    | null, _ -> -1\n    | _, null -> 1\n    | (:? string as x), (:? string as y) -> Scalar.compareText x y\n    | _ when a.GetType().IsGenericType && a.GetType().GetGenericTypeDefinition() = setType ->\n        compareSequence (portableItems a) (portableItems b)\n    | _ when a.GetType().IsGenericType && a.GetType().GetGenericTypeDefinition() = mapType ->\n        compareSequence (portableEntries a) (portableEntries b)\n    | (:? (byte[]) as x), (:? (byte[]) as y) -> Scalar.compareBytes x y\n    | (:? bool as x), (:? bool as y) -> Operators.compare x y\n    | (:? BigInteger as x), (:? BigInteger as y) -> sign (BigInteger.Compare(x, y))\n    | (:? Rune as x), (:? Rune as y) -> Operators.compare x.Value y.Value\n    | (:? float as x), _ -> noOrder x\n    | (:? float32 as x), _ -> noOrder x\n    | (:? Symbol as x), _ -> noOrder x\n    | (:? IPortable as x), _ -> sign (x.CompareTo b)\n    | (:? IComparable as x), _ when a.GetType().IsPrimitive -> sign (x.CompareTo b)\n    | _ when Reflection.FSharpType.IsUnion(a.GetType()) && not (a :? IEnumerable) ->\n        let tag, fields = unionParts (a.GetType())\n        let ta, tb = tag a, tag b\n        if ta <> tb then Operators.compare ta tb\n        else compareSequence (fields a :> IEnumerable) (fields b :> IEnumerable)\n    | (:? IEnumerable as xs), (:? IEnumerable as ys) -> compareSequence xs ys\n    | (:? IComparable as x), _ -> sign (x.CompareTo b)\n    | _ -> noOrder a\n\n/// A Set's items in the portable order.\nand private portableItems (s: obj) : IEnumerable =\n    let items = (s :?> IEnumerable) |> Seq.cast<obj> |> Array.ofSeq\n    items |> Array.sortWith compare :> IEnumerable\n\n/// A Map's entries, each key then its value, in the portable order of the keys.\nand private portableEntries (m: obj) : IEnumerable =\n    let entries =\n        (m :?> IEnumerable) |> Seq.cast<obj>\n        |> Seq.map (fun e ->\n            let t = e.GetType()\n            t.GetProperty(\"Key\").GetValue e, t.GetProperty(\"Value\").GetValue e)\n        |> Array.ofSeq\n        |> Array.sortWith (fun (k, _) (l, _) -> compare k l)\n    entries |> Seq.collect (fun (k, v) -> [ k; v ]) |> Seq.toArray :> IEnumerable\n\nand private compareSequence (xs: IEnumerable) (ys: IEnumerable) =\n    let ys = ys.GetEnumerator()\n    let xs = xs.GetEnumerator()\n    let mutable result = None\n    while result.IsNone do\n        match xs.MoveNext(), ys.MoveNext() with\n        | false, false -> result <- Some 0\n        | false, true -> result <- Some -1\n        | true, false -> result <- Some 1\n        | true, true ->\n            match compare xs.Current ys.Current with\n            | 0 -> ()\n            | c -> result <- Some c\n    result.Value\n\n/// Compare two constructors' ranks and then their fields.\n[<CompiledName(\"CompareData\")>]\nlet compareData (rankA: int) (fieldsA: obj list) (rankB: int) (fieldsB: obj list) =\n    if rankA <> rankB then Operators.compare rankA rankB\n    else\n        let rec go xs ys =\n            match xs, ys with\n            | x :: xs, y :: ys ->\n                match compare x y with\n                | 0 -> go xs ys\n                | c -> c\n            | [], [] -> 0\n            | [], _ -> -1\n            | _, [] -> 1\n        go fieldsA fieldsB\n\n/// Whether two constructors' fields are equal.\n[<CompiledName(\"EqualData\")>]\nlet equalData (rankA: int) (fieldsA: obj list) (rankB: int) (fieldsB: obj list) =\n    rankA = rankB && List.length fieldsA = List.length fieldsB && List.forall2 equal fieldsA fieldsB\n\n/// A hash of a constructor and its fields.\n[<CompiledName(\"HashData\")>]\nlet hashData (rank: int) (fields: obj list) = fields |> List.fold (fun h f -> h * 31 + hash f) (rank + 7)\n"
dotnetSource "LawSpec.Runtime/Random.fs" = "/// The portable SplitMix64 sequence. Its state is passed explicitly, so\n/// concurrent callers never draw from one another's stream, and the same seed\n/// replays the same run on every target. ref:splitmix\n/// ref:DEC-portable-seeded-generation\nmodule LawSpec.Runtime.Random\n\nopen System.Numerics\n\n/// A SplitMix64 state.\n[<Struct>]\ntype Seed = Seed of uint64\n\n/// The state for a seed (any integer, reduced to 64 bits).\n[<CompiledName(\"SeedOf\")>]\nlet seed (n: BigInteger) = Seed(uint64 (n &&& BigInteger(System.UInt64.MaxValue)))\n\n/// The next output and state.\n[<CompiledName(\"Next\")>]\nlet next (Seed state) =\n    let s = state + 0x9e3779b97f4a7c15UL\n    let a = (s ^^^ (s >>> 30)) * 0xbf58476d1ce4e5b9UL\n    let b = (a ^^^ (a >>> 27)) * 0x94d049bb133111ebUL\n    b ^^^ (b >>> 31), Seed s\n\n/// A draw below a bound (0 for a bound that is not positive), as every\n/// runtime reduces it: the output modulo the bound.\n[<CompiledName(\"Below\")>]\nlet below (bound: BigInteger) (state: Seed) =\n    if bound.Sign <= 0 then BigInteger.Zero, state\n    else\n        let n, next' = next state\n        BigInteger.Remainder(BigInteger n, bound), next'\n\n/// Two independent states from one, for generators that branch.\n[<CompiledName(\"Split\")>]\nlet split (state: Seed) =\n    let a, s1 = next state\n    let b, _ = next s1\n    Seed a, Seed b\n"
dotnetSource "LawSpec.Runtime/Recorded.fs" = "/// Typed text for recorded values. Every target writes a recording the same\n/// way, so one recorded file checks every implementation. Identities (symbols\n/// and handles) are numbered within one recording. ref:REQ-law-primitives\n/// ref:DEC-portable-exact-arithmetic\nmodule LawSpec.Runtime.Recorded\n\nopen System\nopen System.Numerics\n\nlet private quote (s: string) = \"\\\"\" + s.Replace(\"\\\\\", \"\\\\\\\\\").Replace(\"\\\"\", \"\\\\\\\"\") + \"\\\"\"\n\nlet private lastPart (tag: string) =\n    let parts = tag.Split(\"::\")\n    parts.[parts.Length - 1]\n\nlet rec private trimDecimal (c: BigInteger) e =\n    if c.IsZero then BigInteger.Zero, 0\n    elif (c % BigInteger 10).IsZero then trimDecimal (c / BigInteger 10) (e + 1)\n    else c, e\n\nlet private floatText value =\n    match value with\n    | Float(w, bits) ->\n        let name = \"float\" + string w\n        if Scalar.floatClass value = \"nan\" then name + \"NaN\"\n        else name + \"Bits(\\\"\" + bits.ToString(if w = 32 then \"x8\" else \"x16\") + \"\\\")\"\n    | _ -> Fail.raiseWith \"InvalidRecordedScalar\" \"float\"\n\nlet private units name (values: int seq) =\n    name + \"([\" + String.Join(\", \", values |> Seq.map string) + \"])\"\n\nlet private scalar value (t: string) =\n    match t, value with\n    | \"Bool\", Bool b -> if b then \"true\" else \"false\"\n    | \"Unit\", Unit -> \"()\"\n    | \"Null\", Null -> \"null\"\n    | \"Undefined\", Undefined -> \"undefined\"\n    | \"Text\", Text s -> quote s\n    | \"Char\", Int n -> quote (Text.Rune(int n).ToString())\n    | (\"CodePoint\" | \"CodeUnit16\"), Int n -> n.ToString()\n    | \"Bytes\", Bytes b -> units \"bytes\" (b |> Seq.map int)\n    | \"CodePointText\", Raw(_, us) -> units \"codePoints\" us\n    | \"Utf16Text\", Raw(_, us) -> units \"utf16\" us\n    | \"Decimal\", Decimal(c, e) ->\n        let c, e = trimDecimal c e\n        c.ToString() + \"e\" + string e\n    | \"Rational\", Ratio(n, d) -> \"rational(\" + n.ToString() + \", \" + d.ToString() + \")\"\n    | (\"Float32\" | \"Float64\"), Float _ -> floatText value\n    | \"Complex64\", Complex(_, r, i) -> \"Complex64(\" + floatText r + \", \" + floatText i + \")\"\n    | \"Complex128\", Complex(_, r, i) -> \"Complex128(\" + floatText r + \", \" + floatText i + \")\"\n    | _, Int n when Scalar.isIntegerType t -> n.ToString()\n    | _ -> Fail.raiseWith \"InvalidRecordedScalar\" t\n\ntype private Ids = Map<string, (obj * int) list>\n\nlet private identity kind (value: obj) (ids: Ids) =\n    let known = defaultArg (ids.TryFind kind) []\n    match known |> List.tryFind (fun (v, _) -> Object.ReferenceEquals(v, value) || v.Equals value) with\n    | Some(_, n) -> n, ids\n    | None ->\n        let n = List.length known + 1\n        n, ids.Add(kind, known @ [ value, n ])\n\nlet rec private render (value: Value) (t: TypeRef) (schema: Schema.Schema option) (ids: Ids) : string * Ids =\n    match t, value with\n    | Named(\"List\", [ element ]), List items ->\n        let (parts: string list), next = sequence items (items |> List.map (fun _ -> element)) schema ids\n        \"[\" + String.Join(\", \", parts) + \"]\", next\n    | Named(kind, [ _ ]), Presence(_, None) -> (if kind = \"Nullable\" then \"null\" else \"undefined\"), ids\n    | Named(kind, [ inner ]), Presence(_, Some v) ->\n        let part, next = render v inner schema ids\n        (if kind = \"Nullable\" then \"nullable(\" else \"optional(\") + part + \")\", next\n    | Named(\"Symbol\", []), Symbol(id, description) ->\n        let n, next = identity \"symbol\" id ids\n        \"symbol(\" + string n + \", \" + quote description + \")\", next\n    | Named(name, []), Handle(_, id) ->\n        let n, next = identity (\"handle \" + name) id ids\n        lastPart name + \"#\" + string n, next\n    | _, Data(tag, fields) ->\n        let types =\n            match t, tag with\n            | _, \"Maybe::Nothing\" -> []\n            | Named(\"Maybe\", [ inner ]), _ -> [ inner ]\n            | Named(\"Either\", [ l; _ ]), \"Either::Left\" -> [ l ]\n            | Named(\"Either\", [ _; r ]), \"Either::Right\" -> [ r ]\n            | _ ->\n                match schema with\n                | Some s -> Schema.fieldTypes value t s\n                | None -> Fail.raiseWith \"RecordingNeedsSchema\" tag\n        let (parts: string list), next = sequence fields types schema ids\n        (if List.isEmpty parts then lastPart tag else lastPart tag + \"(\" + String.Join(\", \", parts) + \")\"), next\n    | Named(name, []), _ -> scalar value name, ids\n    | _ -> Fail.raiseWith \"InvalidRecordedValue\" (Scalar.typeKey t)\n\nand private sequence (values: Value list) (types: TypeRef list) schema ids : string list * Ids =\n    List.zip values types\n    |> List.fold (fun (parts, ids) (v, t) ->\n        let part, next = render v t schema ids\n        parts @ [ part ], next) ([], ids)\n\n/// A value's recorded text at its type.\n[<CompiledName(\"Text\")>]\nlet text (value: Value) (t: TypeRef) (schema: Schema.Schema option) = fst (render value t schema Map.empty)\n\n/// The untyped rendering a model's recorded state uses.\n[<CompiledName(\"Render\")>]\nlet rec renderPlain (value: Value) : string =\n    match value with\n    | Bool true -> \"true\"\n    | Bool false -> \"false\"\n    | Unit -> \"()\"\n    | Int n -> n.ToString()\n    | Text s -> quote s\n    | List items -> \"[\" + String.Join(\", \", items |> List.map renderPlain) + \"]\"\n    | Data(tag, []) -> lastPart tag\n    | Data(tag, fields) -> lastPart tag + \"(\" + String.Join(\", \", fields |> List.map renderPlain) + \")\"\n    | _ -> sprintf \"%A\" value\n"
dotnetSource "LawSpec.Runtime/Regex.fs" = "/// LawSpec's portable regex grammar, on Unicode scalar values rather than\n/// .NET's regex engine and its character classes. A match covers the whole\n/// text, and matching tracks reachable positions, so an ambiguous repeat\n/// never backtracks exponentially. ref:DEC-typed-core-boundary\nmodule LawSpec.Runtime.Regex\n\nopen System.Collections.Concurrent\n\n/// A compiled pattern.\ntype Node =\n    /// A character set: negated, and items each (negated, ranges).\n    | Set of negated: bool * items: (bool * (int * int) list) list\n    | Sequence of Node list\n    | Alternatives of Node list\n    | Repeat of Node * low: int * high: int option\n\nlet private fail reason : 'a = Fail.raiseWith \"NonPortableRegex\" reason\n\nlet private require condition reason = if not condition then fail reason\n\nlet private escape (cs: int list) =\n    match cs with\n    | c :: rest when c = int 'd' || c = int 'D' -> (c = int 'D', [ 48, 57 ]), rest\n    | c :: rest when c = int 'w' || c = int 'W' -> (c = int 'W', [ 48, 57; 65, 90; 95, 95; 97, 122 ]), rest\n    | c :: rest when c = int 's' || c = int 'S' -> (c = int 'S', [ 9, 13; 32, 32 ]), rest\n    | c :: rest ->\n        let named = [ int 'n', 10; int 't', 9; int 'r', 13; int 'f', 12; int 'v', 11 ]\n        match List.tryFind (fun (k, _) -> k = c) named with\n        | Some(_, v) -> (false, [ v, v ]), rest\n        | None ->\n            require (\"\\\\.^$|?*+()[]{}-/\" |> Seq.exists (fun x -> int x = c)) \"UnsupportedEscape\"\n            (false, [ c, c ]), rest\n    | [] -> fail \"TrailingEscape\"\n\nlet private classItem cs =\n    match cs with\n    | c :: rest when c = int '\\\\' -> escape rest\n    | c :: _ when c = int '[' -> fail \"UnescapedClassOpen\"\n    | c :: rest -> (false, [ c, c ]), rest\n    | [] -> fail \"UnclosedClass\"\n\nlet rec private charClass cs negated acc =\n    match cs with\n    | [] -> fail \"UnclosedClass\"\n    | c :: _ when c = int ']' && List.isEmpty acc -> fail \"EmptyClass\"\n    | c :: rest when c = int ']' -> Set(negated, List.rev acc), rest\n    | _ ->\n        let item, rest = classItem cs\n        match item, rest with\n        | (false, [ lo, lo' ]), dash :: c :: tail when lo = lo' && dash = int '-' && c <> int ']' ->\n            match classItem (c :: tail) with\n            | (false, [ hi, hi' ]), next when hi = hi' && hi >= lo -> charClass next negated ((false, [ lo, hi ]) :: acc)\n            | _ -> fail \"InvalidClassRange\"\n        | _ -> charClass rest negated (item :: acc)\n\nlet private count cs =\n    let digits = cs |> List.takeWhile (fun c -> c >= int '0' && c <= int '9')\n    require (not (List.isEmpty digits)) \"MissingRepetitionCount\"\n    let value = digits |> List.fold (fun n d -> n * 10 + (d - int '0')) 0\n    value, List.skip digits.Length cs\n\nlet private repeat node low high cs =\n    require (low <= 1000 && (match high with None -> true | Some h -> h <= 1000 && h >= low)) \"InvalidRepetitionCount\"\n    match cs with\n    | c :: _ -> require (not (\"*+?{\" |> Seq.exists (fun x -> int x = c))) \"RepeatedQuantifier\"\n    | [] -> ()\n    Repeat(node, low, high), cs\n\nlet private quantified node cs =\n    match cs with\n    | c :: rest when c = int '*' -> repeat node 0 None rest\n    | c :: rest when c = int '+' -> repeat node 1 None rest\n    | c :: rest when c = int '?' -> repeat node 0 (Some 1) rest\n    | c :: rest when c = int '{' ->\n        let low, after = count rest\n        match after with\n        | c :: next when c = int '}' -> repeat node low (Some low) next\n        | c :: d :: next when c = int ',' && d = int '}' -> repeat node low None next\n        | c :: tail when c = int ',' ->\n            let high, after = count tail\n            match after with\n            | d :: next when d = int '}' -> repeat node low (Some high) next\n            | _ -> fail \"UnclosedRepetition\"\n        | _ -> fail \"InvalidRepetition\"\n    | _ -> node, cs\n\nlet rec private alternatives cs =\n    let branch, rest = sequence cs []\n    let rec more rest acc =\n        match rest with\n        | c :: tail when c = int '|' ->\n            let next, after = sequence tail []\n            more after (next :: acc)\n        | _ ->\n            match acc with\n            | [ only ] -> only, rest\n            | _ -> Alternatives(List.rev acc), rest\n    more rest [ branch ]\n\nand private sequence cs acc =\n    match cs with\n    | [] -> Sequence(List.rev acc), []\n    | c :: _ when c = int ')' || c = int '|' -> Sequence(List.rev acc), cs\n    | _ ->\n        let atom, rest = atom cs\n        let node, next = quantified atom rest\n        sequence next (node :: acc)\n\nand private atom cs =\n    match cs with\n    | o :: q :: c :: rest when o = int '(' && q = int '?' && c = int ':' -> group rest\n    | o :: q :: _ when o = int '(' && q = int '?' -> fail \"UnsupportedGroup\"\n    | o :: rest when o = int '(' -> group rest\n    | o :: n :: rest when o = int '[' && n = int '^' -> charClass rest true []\n    | o :: rest when o = int '[' -> charClass rest false []\n    | d :: rest when d = int '.' -> Set(true, [ false, [ 10, 10 ] ]), rest\n    | b :: rest when b = int '\\\\' ->\n        let item, after = escape rest\n        Set(false, [ item ]), after\n    | c :: rest ->\n        require (not (\"*+?{^$]}\" |> Seq.exists (fun x -> int x = c))) \"UnexpectedCharacter\"\n        Set(false, [ false, [ c, c ] ]), rest\n    | [] -> fail \"MissingAtom\"\n\nand private group cs =\n    let node, rest = alternatives cs\n    match rest with\n    | c :: next when c = int ')' -> node, next\n    | _ -> fail \"UnclosedGroup\"\n\nlet private cache = ConcurrentDictionary<string, Node>()\n\n/// Compile a pattern once; compiled patterns are shared.\n[<CompiledName(\"Compile\")>]\nlet compile (pattern: string) =\n    cache.GetOrAdd(pattern, fun pattern ->\n        if not (Scalar.isWellFormed pattern) then Fail.raiseWith \"InvalidUnicode\" \"\"\n        let node, rest = alternatives (Scalar.codePoints pattern)\n        require (List.isEmpty rest) \"UnmatchedClosingParenthesis\"\n        node)\n\nlet private inSet (c: int) items =\n    items |> List.exists (fun (negated, ranges) -> negated <> (ranges |> List.exists (fun (lo, hi) -> c >= lo && c <= hi)))\n\nlet rec private reach node (text: int[]) (positions: Set<int>) : Set<int> =\n    match node with\n    | Set(negated, items) ->\n        positions\n        |> Seq.filter (fun p -> p < text.Length && inSet text.[p] items <> negated)\n        |> Seq.map (fun p -> p + 1)\n        |> Set.ofSeq\n    | Sequence nodes -> nodes |> List.fold (fun ps n -> reach n text ps) positions\n    | Alternatives nodes -> nodes |> List.map (fun n -> reach n text positions) |> Set.unionMany\n    | Repeat(inner, low, high) ->\n        let mutable required = positions\n        let mutable i = 0\n        while i < low && not required.IsEmpty do\n            required <- reach inner text required\n            i <- i + 1\n        let mutable seen = required\n        let mutable frontier = required\n        let mutable remaining = high |> Option.map (fun h -> h - low)\n        while not frontier.IsEmpty && remaining <> Some 0 do\n            let next = Set.difference (reach inner text frontier) seen\n            seen <- Set.union seen next\n            frontier <- next\n            remaining <- remaining |> Option.map (fun r -> r - 1)\n        seen\n\n/// Whether a compiled pattern matches the whole text.\n[<CompiledName(\"Run\")>]\nlet run (node: Node) (text: string) =\n    let points = Scalar.codePoints text |> Array.ofList\n    reach node points (Set.singleton 0) |> Set.contains points.Length\n\n/// Whether a pattern matches the whole text.\n[<CompiledName(\"Matches\")>]\nlet matches (pattern: string) (text: string) = run (compile pattern) text\n"
dotnetSource "LawSpec.Runtime/Remote.fs" = "namespace LawSpec.Runtime\n\nopen System\nopen System.Text\n\n/// One selectable remote function: its arguments' and result's descriptor\n/// texts, and (on the serving side) its body over portable values.\ntype RemoteEntry =\n    { Arguments: string list\n      Result: string\n      Invoke: (Value list -> Value) option }\n\n/// A connection to a remote service: a node, the service's address, its\n/// request kind, the signatures by selector, and the timeout in ms.\ntype RemoteClient =\n    { Node: Node\n      Address: string\n      Kind: string\n      Signatures: Map<string, (Map<string, Descriptors.Descriptor> * Descriptors.Descriptor) list * (Map<string, Descriptors.Descriptor> * Descriptors.Descriptor)>\n      Timeout: int }\n\n/// Actors and checked definitions answer the same canonical requests: a\n/// selector (a message name, or a definition's content hash) and its\n/// arguments, each in the canonical wire encoding; the reply is the result.\n/// ref:DEC-distribution-canonical-wire ref:DEC-async-native-tasks\nmodule Remote =\n    let private fail reason : 'a = Fail.raiseWith \"Remote\" reason\n    let private textType = Descriptors.Forms [ Descriptors.Atom \"text\" ]\n\n    let private compile (entry: RemoteEntry) =\n        entry.Arguments |> List.map Descriptors.fromText, Descriptors.fromText entry.Result\n\n    let private printable (e: exn) =\n        Encoding.UTF8.GetBytes(match e with :? LawSpecException as l -> l.Message | _ -> e.GetType().Name + \": \" + e.Message)\n\n    /// Serve a table of selectors at a name on a node (\"call\" for actors,\n    /// \"eval\" for definitions); the service's address.\n    [<CompiledName(\"Serve\")>]\n    let serve (node: Node) (name: string) (kind: string) (table: (string * RemoteEntry) list) : string =\n        if kind <> \"call\" && kind <> \"eval\" then fail \"invalid_kind\"\n        let compiled =\n            table\n            |> List.map (fun (selector, entry) ->\n                if entry.Invoke.IsNone then fail \"invalid_remote_function\"\n                selector, (compile entry, entry.Invoke.Value))\n            |> Map.ofList\n        node.RegisterHandler(name, fun frame ->\n            if frame.Kind <> kind then 3, Encoding.UTF8.GetBytes \"this service does not handle that request kind\"\n            else\n                let parsed =\n                    try\n                        match Descriptors.decodePrefix textType frame.Payload 0 Map.empty with\n                        | Text selector, start ->\n                            let (arguments, result), invoke = compiled.[selector]\n                            let mutable at = start\n                            let values =\n                                [ for table, d in arguments ->\n                                      let v, next = Descriptors.decodePrefix d frame.Payload at table\n                                      at <- next\n                                      v ]\n                            if at <> frame.Payload.Length then None else Some(values, result, invoke)\n                        | _ -> None\n                    with _ -> None\n                match parsed with\n                | None -> 3, Encoding.UTF8.GetBytes \"unknown selector or malformed remote arguments\"\n                | Some(values, (table, d), invoke) ->\n                    try 0, Descriptors.encode d (invoke values) table with\n                    | :? LawSpecException as e when e.Code = \"ActorStopped\" -> 2, Encoding.UTF8.GetBytes \"the actor has stopped\"\n                    | e -> 1, printable e)\n\n    /// A client of a remote service.\n    [<CompiledName(\"Connect\")>]\n    let connect (node: Node) (address: string) (kind: string) (signatures: (string * RemoteEntry) list) (timeout: int) : RemoteClient =\n        if timeout < 0 then fail \"invalid_timeout\"\n        Wire.splitAddress address |> ignore\n        { Node = node; Address = address; Kind = kind; Timeout = timeout\n          Signatures = signatures |> List.map (fun (s, e) -> s, compile e) |> Map.ofList }\n\n    /// Call a selector with portable arguments; its portable result.\n    [<CompiledName(\"Call\")>]\n    let call (client: RemoteClient) (selector: string) (arguments: Value list) : Value =\n        let types, (resultTable, resultType) =\n            match client.Signatures.TryFind selector with\n            | Some s -> s\n            | None -> fail (\"unknown_selector \" + selector)\n        if List.length types <> List.length arguments then fail \"argument_count\"\n        let payload =\n            Array.concat (\n                Descriptors.encode textType (Text selector) Map.empty\n                :: List.map2 (fun (table, d) v -> Descriptors.encode d v table) types arguments)\n        match client.Node.Request(client.Address, client.Kind, payload, client.Timeout) with\n        | 0, bytes -> Descriptors.decode resultType bytes resultTable\n        | 1, message -> fail (\"failed \" + Encoding.UTF8.GetString message)\n        | 2, message -> fail (\"stopped \" + Encoding.UTF8.GetString message)\n        | 3, message -> fail (\"rejected \" + Encoding.UTF8.GetString message)\n        | status, _ -> fail (\"invalid_reply_status \" + string status)\n"
dotnetSource "LawSpec.Runtime/Runtime.fs" = "/// Services the generated definitions and laws share: contracts, equations,\n/// helpers, recordings and concurrent groups. Values stay portable until a\n/// native boundary. ref:DEC-typed-core-boundary\nmodule LawSpec.Runtime.Runtime\n\nopen System\nopen System.IO\nopen System.Threading.Tasks\n\n/// A portable boolean as a .NET one.\n[<CompiledName(\"Truth\")>]\nlet truth (value: Value) =\n    match value with\n    | Bool b -> b\n    | _ -> Fail.raiseWith \"BoolRequired\" (sprintf \"%A\" value)\n\n[<CompiledName(\"Not\")>]\nlet not (value: Value) = Bool(Operators.not (truth value))\n\n/// The item of a list of values at a position.\n[<CompiledName(\"Item\")>]\nlet item (index: int) (values: Value list) = List.item index values\n\n/// The item of a list at a position.\n[<CompiledName(\"Nth\")>]\nlet nth (index: int) (items: 'a list) = List.item index items\n\n[<CompiledName(\"Some\")>]\nlet some (value: 'a) = Some value\n\n/// A data value's field at a position (a list's head and tail).\n[<CompiledName(\"Field\")>]\nlet field (value: Value) (index: int) =\n    match value, index with\n    | Data(_, fields), _ -> List.item index fields\n    | List(head :: _), 0 -> head\n    | List(_ :: tail), 1 -> List tail\n    | _ -> Fail.raiseWith \"ExpectedData\" (sprintf \"%A\" value)\n\n/// Whether a value was built by a constructor.\n[<CompiledName(\"HasTag\")>]\nlet hasTag (tag: string) (value: Value) =\n    match value with\n    | Data(t, _) -> t = tag\n    | List [] -> tag = \"List::Nil\"\n    | List _ -> tag = \"List::Cons\"\n    | _ -> false\n\n/// A match no branch covers.\n[<CompiledName(\"NoMatch\")>]\nlet noMatch (value: Value) : Value = Fail.raiseWith \"MatchFailure\" (sprintf \"%A\" value)\n\n/// Whether every element of a list satisfies a predicate.\n[<CompiledName(\"AllElements\")>]\nlet allElements (value: Value) (predicate: Value -> Value) =\n    match value with\n    | List items -> Bool(items |> List.forall (predicate >> truth))\n    | _ -> Fail.raiseWith \"ListRequired\" \"\"\n\n/// Whether every payload of a container satisfies its parameter's predicate.\n[<CompiledName(\"AllPayloads\")>]\nlet allPayloads (value: Value) (t: TypeRef) (predicates: (Value -> Value) list) (schema: Schema.Schema) =\n    Bool(Schema.allPayloads value t (predicates |> List.map (fun p -> p >> truth)) schema)\n\n/// Nullable or Optional, absent.\n[<CompiledName(\"Absent\")>]\nlet absent (kind: string) = Presence(kind, None)\n\n/// Nullable or Optional, present.\n[<CompiledName(\"Present\")>]\nlet present (kind: string) (value: Value) = Presence(kind, Some value)\n\n/// Fail a contract unless it holds.\n[<CompiledName(\"Require\")>]\nlet require (holds: Value) (context: string) : unit =\n    match holds with\n    | Bool true -> ()\n    | Bool false -> Fail.raiseWith \"ContractFailed\" context\n    | _ -> Fail.raiseWith \"NonBooleanContract\" context\n\n/// Where two unequal values first differ: the path to the item or field,\n/// and both values there.\nlet private difference (actual: Value) (expected: Value) =\n    let rec walk (a: Value) (b: Value) (path: string list) =\n        match a, b with\n        | List xs, List ys ->\n            let firstDiff =\n                Seq.zip xs ys |> Seq.tryFindIndex (fun (x, y) -> Recorded.renderPlain x <> Recorded.renderPlain y)\n            match firstDiff with\n            | Some i -> walk (List.item i xs) (List.item i ys) (path @ [ sprintf \"item %d\" (i + 1) ])\n            | None when List.length xs = List.length ys -> None\n            | None -> Some(path @ [ \"length\" ], string (List.length xs), string (List.length ys))\n        | Data(tx, fx), Data(ty, fy) when tx = ty && List.length fx = List.length fy ->\n            let name = tx.Substring(tx.LastIndexOf(\"::\") + 2)\n            match List.zip fx fy |> List.tryFindIndex (fun (x, y) -> Recorded.renderPlain x <> Recorded.renderPlain y) with\n            | Some i -> walk (List.item i fx) (List.item i fy) (path @ [ sprintf \"field %d of %s\" (i + 1) name ])\n            | None -> None\n        | _ when List.isEmpty path -> None\n        | _ -> Some(path, Recorded.renderPlain a, Recorded.renderPlain b)\n    match walk actual expected [] with\n    | Some(path, shownActual, shownExpected) ->\n        sprintf \" | first difference at %s: expected %s, actual %s\" (String.Join(\", \", path)) shownExpected shownActual\n    | None -> \"\"\n\n/// An equation of a law: both sides are kept for the report.\n[<CompiledName(\"AssertEqual\")>]\nlet assertEqual (actual: Value) (expected: Value) (label: string) : Value =\n    if Scalar.equal actual expected then Bool true\n    else\n        Fail.raiseWith \"EquationFailed\"\n            (sprintf \"%s: actual %s, expected %s%s\" label (Recorded.renderPlain actual) (Recorded.renderPlain expected) (difference actual expected))\n\n/// Name the definition or law a LawSpec failure happened in.\n[<CompiledName(\"Contextual\")>]\nlet contextual (identity: string) (body: unit -> 'a) : 'a =\n    try body () with\n    | :? LawSpecException as e -> raise (e.Within identity)\n\nlet private recordedRoot () =\n    match Environment.GetEnvironmentVariable \"LAWSPEC_RECORDED\" with\n    | null | \"\" ->\n        let start = Directory.GetCurrentDirectory()\n        let rec find (folder: string) =\n            if File.Exists(Path.Combine(folder, \"lawspec.json\")) || Directory.Exists(Path.Combine(folder, \"recorded\")) then\n                Path.Combine(folder, \"recorded\")\n            else\n                match Directory.GetParent folder with\n                | null -> Path.Combine(start, \"recorded\")\n                | parent -> find parent.FullName\n        find start\n    | given -> given\n\n/// Compare a value's text with its recording, or record it under\n/// LAWSPEC_UPDATE_RECORDED=1 (lawspec test --update-recorded).\n[<CompiledName(\"RecordedText\")>]\nlet recordedText (key: string) (text: string) : Value =\n    let path = Path.Combine(Array.append [| recordedRoot () |] (key.Split '/'))\n    if Environment.GetEnvironmentVariable \"LAWSPEC_UPDATE_RECORDED\" = \"1\" then\n        Directory.CreateDirectory(Path.GetDirectoryName path) |> ignore\n        File.WriteAllText(path, text + \"\\n\")\n        Bool true\n    elif File.Exists path then\n        let stored = File.ReadAllText path\n        let stored = if stored.EndsWith \"\\n\" then stored.Substring(0, stored.Length - 1) else stored\n        if stored = text then Bool true\n        else\n            Fail.raiseWith \"RecordingDiffers\"\n                (\"recorded/\" + key + \" differs: expected \" + stored + \", actual \" + text\n                 + \" (lawspec test --update-recorded records the new value)\")\n    else\n        Fail.raiseWith \"RecordingMissing\"\n            (\"no recording recorded/\" + key + \"; run lawspec test --update-recorded to record \" + text)\n\n/// A recorded value, at its type.\n[<CompiledName(\"Recorded\")>]\nlet recorded (key: Value) (value: Value) (t: TypeRef) (schema: Schema.Schema) : Value =\n    match key with\n    | Text k -> recordedText k (Recorded.text value t (Some schema))\n    | _ -> Fail.raiseWith \"TextRequired\" \"recorded\"\n\n/// A built-in helper by name.\n[<CompiledName(\"Helper\")>]\nlet helper (name: string) (values: Value list) (types: string list) (bits: int) : Value =\n    match name, values with\n    | \"unreachable\", _ -> Fail.raiseWith \"Unreachable\" \"\"\n    | \"regexMatches\", [ Text pattern; Text text ] -> Bool(Regex.matches pattern text)\n    | \"recorded\", [ Text key; value ] when List.length types < 2 -> recordedText key (Recorded.renderPlain value)\n    | \"recorded\", [ key; value ] -> recorded key value (Scalar.typeOf (List.item 1 types)) (Schema.create [] [] bits)\n    | _ -> Scalar.helper name values types bits\n\nlet private unwrap (e: exn) =\n    match e with\n    | :? AggregateException as a when a.InnerExceptions.Count = 1 -> a.InnerExceptions.[0]\n    | _ -> e\n\n/// Run steps concurrently, each on the thread pool, and return their values\n/// in source order. Every step finishes before the first failure in source\n/// order is raised.\n[<CompiledName(\"Concurrently\")>]\nlet concurrently (steps: (unit -> Value) list) : Value list =\n    let tasks = steps |> List.map (fun step -> Task.Run(fun () -> step ())) |> Array.ofList\n    try Task.WaitAll(tasks |> Array.map (fun t -> t :> Task)) with _ -> ()\n    tasks\n    |> Array.map (fun t ->\n        if t.IsFaulted then raise (unwrap t.Exception)\n        elif t.IsCanceled then Fail.raiseWith \"ConcurrentStepCancelled\" \"\"\n        else t.Result)\n    |> List.ofArray\n\n/// Await an async adapter's task where it is called.\n[<CompiledName(\"Await\")>]\nlet await (task: Task<'a>) : 'a =\n    try task.GetAwaiter().GetResult() with e -> raise (unwrap e)\n\n/// Await a task with no result (a C# adapter's Task).\n[<CompiledName(\"AwaitDone\")>]\nlet awaitDone (task: Task) : unit =\n    try task.GetAwaiter().GetResult() with e -> raise (unwrap e)\n\n/// Discard a value computed for its checks.\n[<CompiledName(\"Ignore\")>]\nlet ignore (_: Value) = ()\n\n/// An integer value from its digits.\n[<CompiledName(\"Integer\")>]\nlet integer (digits: string) = Int(Numerics.BigInteger.Parse digits)\n"
dotnetSource "LawSpec.Runtime/Scalar.fs" = "/// LawSpec's scalar domain on .NET. Exact arithmetic never goes through a\n/// native float, and IEEE values are rounded once, from an exact ratio, to\n/// nearest with ties to even. Every generated law and dynamic definition uses\n/// these operations, so F# and C# agree with each other and with the other\n/// targets. ref:DEC-portable-exact-arithmetic ref:ieee-754\n/// ref:DEC-explicit-machine-profile\nmodule LawSpec.Runtime.Scalar\n\nopen System\nopen System.Collections.Concurrent\nopen System.Numerics\nopen System.Text\n\nlet private fail code detail : 'a = Fail.raiseWith code detail\n\n// ---------------------------------------------------------------------------\n// Type keys\n\nlet private tokenize (text: string) =\n    let tokens = ResizeArray<string>()\n    let word = StringBuilder()\n    let flush () =\n        if word.Length > 0 then\n            tokens.Add(word.ToString())\n            word.Clear() |> ignore\n    for c in text do\n        match c with\n        | '(' | ')' ->\n            flush ()\n            tokens.Add(string c)\n        | ' ' | '\\t' -> flush ()\n        | c -> word.Append(c) |> ignore\n    flush ()\n    List.ofSeq tokens\n\nlet rec private application parts =\n    match parts with\n    | [ Named(name, []) ] -> Named(name, [])\n    | Named(name, []) :: args when List.contains name [ \"List\"; \"Maybe\"; \"Optional\"; \"Nullable\" ] ->\n        Named(name, [ application args ])\n    | Named(name, []) :: args -> Named(name, args)\n    | [ t ] -> t\n    | _ -> fail \"InvalidTypeKey\" \"\"\n\nlet rec private parts tokens acc =\n    match tokens with\n    | [] -> List.rev acc, []\n    | \")\" :: _ -> List.rev acc, tokens\n    | \"(\" :: rest ->\n        let inner, after = parts rest []\n        match after with\n        | \")\" :: next -> parts next (application inner :: acc)\n        | _ -> fail \"InvalidTypeKey\" \"\"\n    | word :: rest when word.StartsWith \"$\" -> parts rest (Parameter(int (word.Substring 1)) :: acc)\n    | word :: rest -> parts rest (Named(word, []) :: acc)\n\nlet private typeCache = ConcurrentDictionary<string, TypeRef>()\n\n/// The type a key names: `Either (Int8) (Text)`, `List Int8`, `Maybe (List Text)`.\n/// Parentheses keep nested Either and presence arguments apart.\n[<CompiledName(\"TypeOf\")>]\nlet typeOf (key: string) : TypeRef =\n    typeCache.GetOrAdd(key, fun key ->\n        let found, rest = parts (tokenize key) []\n        if not (List.isEmpty rest) then fail \"InvalidTypeKey\" key\n        application found)\n\n/// The key of a type, as typeOf reads it.\n[<CompiledName(\"TypeKey\")>]\nlet rec typeKey (t: TypeRef) =\n    match t with\n    | Named(name, []) -> name\n    | Named(name, args) -> name + String.Join(\"\", args |> List.map (fun a -> \" (\" + typeKey a + \")\"))\n    | Parameter i -> sprintf \"$%d\" i\n\nlet private nameOf (t: TypeRef) =\n    match t with\n    | Named(name, _) -> name\n    | Parameter _ -> \"\"\n\n// ---------------------------------------------------------------------------\n// Integers\n\nlet private integerTypes =\n    set [ \"Int8\"; \"Int16\"; \"Int32\"; \"Int64\"; \"UInt8\"; \"UInt16\"; \"UInt32\"; \"UInt64\"\n          \"IntSize\"; \"UIntSize\"; \"UIntPtr\"; \"Integer\"; \"BigInt\"; \"BigUInt\" ]\n\n/// Whether a scalar name is one of LawSpec's integer types.\n[<CompiledName(\"IsIntegerType\")>]\nlet isIntegerType name = integerTypes.Contains name\n\nlet private pow2 (n: int) = BigInteger.One <<< n\n\nlet private signed (width: int) = Some(-(pow2 (width - 1))), Some(pow2 (width - 1) - BigInteger.One)\n\n/// An integer type's inclusive bounds under a machine profile (32 or 64 bits).\n[<CompiledName(\"Bounds\")>]\nlet bounds (name: string) (bits: int) : BigInteger option * BigInteger option =\n    if bits <> 32 && bits <> 64 then fail \"InvalidMachineBits\" (string bits)\n    match name with\n    | \"Integer\" | \"BigInt\" -> None, None\n    | \"BigUInt\" -> Some BigInteger.Zero, None\n    | \"IntSize\" -> signed bits\n    | \"UIntSize\" | \"UIntPtr\" -> Some BigInteger.Zero, Some(pow2 bits - BigInteger.One)\n    | _ when name.StartsWith \"UInt\" -> Some BigInteger.Zero, Some(pow2 (int (name.Substring 4)) - BigInteger.One)\n    | _ when name.StartsWith \"Int\" -> signed (int (name.Substring 3))\n    | _ -> fail \"UnknownInteger\" name\n\nlet private checkBounds (value: BigInteger) name bits =\n    let lo, hi = bounds name bits\n    let below = match lo with Some l -> value < l | None -> false\n    let above = match hi with Some h -> value > h | None -> false\n    if below || above then fail \"IntegerOutOfRange\" (sprintf \"%s %O\" name value)\n    Int value\n\n// ---------------------------------------------------------------------------\n// Exact numbers\n\n/// A normalized fraction.\n[<CompiledName(\"Ratio\")>]\nlet ratio (n: BigInteger) (d: BigInteger) =\n    if d.IsZero then fail \"InvalidRational\" \"zero denominator\"\n    let g = BigInteger.GreatestCommonDivisor(n, d)\n    let s = if d.Sign < 0 then BigInteger.MinusOne else BigInteger.One\n    Ratio(s * n / g, BigInteger.Abs d / g)\n\nlet private pow10 (n: int) = BigInteger.Pow(BigInteger(10), n)\n\nlet private normalized n d =\n    match ratio n d with\n    | Ratio(a, b) -> a, b\n    | _ -> failwith \"unreachable\"\n\n// IEEE layouts: fraction bits, exponent bits, bias.\nlet private format width =\n    match width with\n    | 32 -> 23, 8, 127\n    | 64 -> 52, 11, 1023\n    | _ -> fail \"InvalidIeeeWidth\" (string width)\n\ntype private Decoded =\n    | Finite of sign: int * mantissa: BigInteger * exponent: int\n    | Infinity of sign: int\n    | NaN\n\nlet private decode width (bits: uint64) =\n    let p, e, bias = format width\n    let sign = int (bits >>> (width - 1)) &&& 1\n    let exponent = int ((bits >>> p) &&& ((1UL <<< e) - 1UL))\n    let fraction = bits &&& ((1UL <<< p) - 1UL)\n    let top = (1 <<< e) - 1\n    if exponent = top then (if fraction = 0UL then Infinity sign else NaN)\n    elif exponent = 0 then Finite(sign, BigInteger(fraction), 1 - bias - p)\n    else Finite(sign, BigInteger((1UL <<< p) + fraction), exponent - bias - p)\n\n/// The exact ratio of an exact number or a finite float.\n[<CompiledName(\"Exact\")>]\nlet exact (value: Value) : BigInteger * BigInteger =\n    match value with\n    | Int n -> n, BigInteger.One\n    | Ratio(n, d) -> n, d\n    | Decimal(c, _) when c.IsZero -> BigInteger.Zero, BigInteger.One\n    | Decimal(c, e) when e >= 0 -> c * pow10 e, BigInteger.One\n    | Decimal(c, e) -> normalized c (pow10 -e)\n    | Float(w, b) ->\n        match decode w b with\n        | Finite(sign, m, e) ->\n            let signedM = if sign = 0 then m else -m\n            if e >= 0 then signedM <<< e, BigInteger.One else normalized signedM (pow2 -e)\n        | _ -> fail \"NonFiniteExactConversion\" \"\"\n    | _ -> fail \"ExactNumberRequired\" (sprintf \"%A\" value)\n\nlet private isExact value =\n    match value with\n    | Int _ | Ratio _ | Decimal _ -> true\n    | _ -> false\n\nlet rec private factors (n: BigInteger) (factor: BigInteger) count =\n    if (n % factor).IsZero then factors (n / factor) factor (count + 1) else n, count\n\n/// A decimal for an exact ratio, when its expansion terminates in base ten.\nlet private finiteDecimal n d =\n    let rn, rd = normalized n d\n    let d2, twos = factors rd (BigInteger 2) 0\n    let d5, fives = factors d2 (BigInteger 5) 0\n    if not d5.IsOne then fail \"NonTerminatingDecimal\" \"\"\n    let scale = max twos fives\n    Value.Decimal(rn * BigInteger.Pow(BigInteger 2, scale - twos) * BigInteger.Pow(BigInteger 5, scale - fives), -scale)\n\n// ---------------------------------------------------------------------------\n// IEEE floats\n\nlet private floatValue width (bits: uint64) =\n    if width = 32 && bits > 0xFFFFFFFFUL then fail \"InvalidIeeeBits\" \"\"\n    Float(width, bits)\n\nlet private zero width sign = Float(width, uint64 sign <<< (width - 1))\n\nlet private infinity width sign =\n    let p, e, _ = format width\n    Float(width, (uint64 sign <<< (width - 1)) ||| (((1UL <<< e) - 1UL) <<< p))\n\nlet private nan width =\n    let p, _, _ = format width\n    match infinity width 0 with\n    | Float(_, inf) -> Float(width, inf ||| (1UL <<< (p - 1)))\n    | _ -> failwith \"unreachable\"\n\nlet private floorLog2 (n: BigInteger) (d: BigInteger) =\n    let guess = int (n.GetBitLength()) - int (d.GetBitLength())\n    let below = if guess >= 0 then n < (d <<< guess) else (n <<< -guess) < d\n    if below then guess - 1 else guess\n\nlet private roundRatio (n: BigInteger) (d: BigInteger) =\n    let q = BigInteger.Divide(n, d)\n    let r = n - q * d\n    if BigInteger 2 * r > d || (BigInteger 2 * r = d && not q.IsEven) then q + BigInteger.One else q\n\n/// The float of a width nearest an exact ratio; a zero takes the given sign.\n[<CompiledName(\"FloatFromRatio\")>]\nlet floatFromRatio width (n: BigInteger) (d: BigInteger) zeroSign =\n    if d.IsZero then fail \"ZeroDenominator\" \"\"\n    if n.IsZero then zero width zeroSign else\n    let p, _, bias = format width\n    let s = if (n.Sign < 0) <> (d.Sign < 0) then 1 else 0\n    let an, ad = BigInteger.Abs n, BigInteger.Abs d\n    let exponent = max (1 - bias) (floorLog2 an ad)\n    let shift = p - exponent\n    let mantissa = if shift >= 0 then roundRatio (an <<< shift) ad else roundRatio an (ad <<< -shift)\n    let m, e = if mantissa >= pow2 (p + 1) then mantissa >>> 1, exponent + 1 else mantissa, exponent\n    if e > bias then infinity width s\n    else\n        let encoded = if m < pow2 p then 0UL else uint64 (e + bias)\n        let fraction = uint64 (m &&& (pow2 p - BigInteger.One))\n        Float(width, (uint64 s <<< (width - 1)) ||| (encoded <<< p) ||| fraction)\n\n/// A float's class: \"nan\", \"infinity\", \"zero\" or \"finite\".\n[<CompiledName(\"FloatClass\")>]\nlet floatClass value =\n    match value with\n    | Float(w, b) ->\n        match decode w b with\n        | NaN -> \"nan\"\n     